package realmflow2

import (
    "strconv"
    "strings"
)

type Scenario struct {
    ID int
    Author address
    Title string
    TargetRealm string
    Payload string
    VerifyCount int
}

var scenarios []Scenario

func RegisterScenario(cur realm, title string, targetRealm string, payload string) int {
    id := len(scenarios) + 1
    scenarios = append(scenarios, Scenario{id, cur.Previous().Address(), title, targetRealm, payload, 0})
    return id
}

func VerifyScenario(cur realm, id int) int {
    if id < 1 || id > len(scenarios) { panic("scenario not found") }
    scenarios[id-1].VerifyCount++
    return scenarios[id-1].VerifyCount
}

func GetScenario(id int) string {
    if id < 1 || id > len(scenarios) { return "" }
    s := scenarios[id-1]
    return strconv.Itoa(s.ID) + " | " + s.Author.String() + " | " + s.Title + " | " + s.TargetRealm + " | " + s.Payload + " | " + strconv.Itoa(s.VerifyCount)
}

func GetScenarioCount() int { return len(scenarios) }

func cell(s string) string {
    return strings.ReplaceAll(strings.ReplaceAll(s, "\n", " "), "|", "\\|")
}

func Render(path string) string {
    path = strings.Trim(path, "/")
    if strings.HasPrefix(path, "scenario/") {
        id, err := strconv.Atoi(strings.TrimPrefix(path, "scenario/"))
        if err != nil || id < 1 || id > len(scenarios) { return "# Scenario not found" }
        s := scenarios[id-1]
        return "# " + cell(s.Title) + "\n\n- **ID:** " + strconv.Itoa(s.ID) + "\n- **Target realm:** `" + cell(s.TargetRealm) + "`\n- **Verifications:** " + strconv.Itoa(s.VerifyCount) + "\n- **Author:** `" + s.Author.String() + "`\n\n[Open in RealmFlow](https://realm-flow.vercel.app/?s=" + s.Payload + ")\n\n[Back to catalog](../)"
    }
    if path != "" { return "# Page not found" }
    var b strings.Builder
    b.WriteString("# RealmFlow Registry\n\nShared realm scenarios.\n\n| ID | Title | Target Realm | Verifications | Author | Open in RealmFlow |\n| --- | --- | --- | --- | --- | --- |\n")
    for _, s := range scenarios {
        id := strconv.Itoa(s.ID)
        b.WriteString("| [" + id + "](scenario/" + id + ") | " + cell(s.Title) + " | " + cell(s.TargetRealm) + " | " + strconv.Itoa(s.VerifyCount) + " | " + s.Author.String() + " | [Open](https://realm-flow.vercel.app/?s=" + s.Payload + ") |\n")
    }
    return b.String()
}

package realmflow2

import (
	"strings"
	"testing"
)

func TestScenarioLifecycle(t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(address("g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5")))
	before := GetScenarioCount()
	id := RegisterScenario(cross, "First scenario", "gno.land/r/demo/boards", "payload")
	if id != before+1 || GetScenarioCount() != before+1 {
		t.Fatal("scenario was not registered")
	}
	if !strings.Contains(GetScenario(id), "First scenario | gno.land/r/demo/boards | payload | 0") {
		t.Fatal("scenario was not returned")
	}
	if VerifyScenario(cross, id) != 1 || VerifyScenario(cross, id) != 2 {
		t.Fatal("verification count was not incremented")
	}
	if !strings.HasSuffix(GetScenario(id), " | 2") {
		t.Fatal("verification count was not stored")
	}
	if GetScenario(0) != "" {
		t.Fatal("invalid ID should return empty string")
	}
	if !strings.Contains(Render(""), "First scenario") || !strings.Contains(Render(""), "| 2 |") {
		t.Fatal("catalog missing scenario or count")
	}
	if !strings.Contains(Render("scenario/1"), "First scenario") || !strings.Contains(Render("scenario/1"), "?s=payload") {
		t.Fatal("detail missing scenario or link")
	}
}

package bounty

import (
	"errors"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

var (
	ErrNotFound      = errors.New("bounty: not found")
	ErrNotOpen       = errors.New("bounty: bounty is not open")
	ErrNotClaimed    = errors.New("bounty: bounty is not claimed")
	ErrNotSubmitted  = errors.New("bounty: bounty has no pending submission")
	ErrNotPoster     = errors.New("bounty: only the poster can do this")
	ErrNotHunter     = errors.New("bounty: only the current hunter can do this")
	ErrOwnBounty     = errors.New("bounty: you cannot claim your own bounty")
	ErrClaimExpired  = errors.New("bounty: claim window has expired")
	ErrClaimActive   = errors.New("bounty: claim window has not expired yet")
	ErrReviewActive  = errors.New("bounty: review window has not expired yet")
	ErrRewardTooLow  = errors.New("bounty: reward is below the board minimum")
	ErrBadTitle      = errors.New("bounty: title must be 1-80 characters")
	ErrBadDesc       = errors.New("bounty: description is too long")
	ErrBadProof      = errors.New("bounty: proof must be 1-280 characters")
	ErrBadNote       = errors.New("bounty: note is too long")
	ErrBadWindow     = errors.New("bounty: claim window out of range")
	ErrInvalidCaller = errors.New("bounty: invalid caller address")
)

const (
	MaxTitleLen = 80
	MaxDescLen  = 2000
	MaxProofLen = 280
	MaxNoteLen  = 280
)

// Config tunes a Board. Zero values fall back to DefaultConfig.
type Config struct {
	MinReward      int64         // smallest reward accepted by Post
	MinClaimWindow time.Duration // shortest claim window a poster may set
	MaxClaimWindow time.Duration // longest claim window a poster may set
	ReviewWindow   time.Duration // after this, an unreviewed submission can be collected by the hunter
}

// DefaultConfig is used for every zero field of the Config passed to NewBoard.
var DefaultConfig = Config{
	MinReward:      1_000_000, // 1 GNOT in ugnot
	MinClaimWindow: time.Hour,
	MaxClaimWindow: 30 * 24 * time.Hour,
	ReviewWindow:   72 * time.Hour,
}

// Board is a bounty board. Keep it unexported in your realm and expose only
// crossing functions: whoever holds the pointer can mutate it.
type Board struct {
	cfg      Config
	ids      seqid.ID
	bounties *avl.Tree // seqid binary key -> *Bounty
	stats    *avl.Tree // address string -> *Stats

	escrowed int64 // rewards currently locked (open, claimed, submitted)
	paid     int64 // rewards paid out over the board's life
}

// NewBoard creates an empty board.
func NewBoard(cfg Config) *Board {
	if cfg.MinReward <= 0 {
		cfg.MinReward = DefaultConfig.MinReward
	}
	if cfg.MinClaimWindow <= 0 {
		cfg.MinClaimWindow = DefaultConfig.MinClaimWindow
	}
	if cfg.MaxClaimWindow <= 0 {
		cfg.MaxClaimWindow = DefaultConfig.MaxClaimWindow
	}
	if cfg.ReviewWindow <= 0 {
		cfg.ReviewWindow = DefaultConfig.ReviewWindow
	}
	return &Board{
		cfg:      cfg,
		bounties: avl.NewTree(),
		stats:    avl.NewTree(),
	}
}

// Config returns the board configuration.
func (bd *Board) Config() Config { return bd.cfg }

// Escrowed is the sum of rewards the owning realm must currently hold.
func (bd *Board) Escrowed() int64 { return bd.escrowed }

// TotalPaid is the sum of rewards paid out so far.
func (bd *Board) TotalPaid() int64 { return bd.paid }

// Size is the number of bounties ever posted.
func (bd *Board) Size() int { return bd.bounties.Size() }

// ReviewDeadline is the time after which the hunter may collect an
// unreviewed submission.
func (bd *Board) ReviewDeadline(b *Bounty) time.Time {
	return b.SubmittedAt.Add(bd.cfg.ReviewWindow)
}

// Post creates a new open bounty. The caller (realm) must already hold reward
// in escrow when calling this.
func (bd *Board) Post(poster address, title, description string, reward int64, claimWindow time.Duration, now time.Time) (*Bounty, error) {
	if !poster.IsValid() {
		return nil, ErrInvalidCaller
	}
	title = strings.TrimSpace(title)
	if len(title) == 0 || len(title) > MaxTitleLen {
		return nil, ErrBadTitle
	}
	description = strings.TrimSpace(description)
	if len(description) > MaxDescLen {
		return nil, ErrBadDesc
	}
	if reward < bd.cfg.MinReward {
		return nil, ErrRewardTooLow
	}
	if claimWindow < bd.cfg.MinClaimWindow || claimWindow > bd.cfg.MaxClaimWindow {
		return nil, ErrBadWindow
	}

	id := bd.ids.Next()
	b := &Bounty{
		ID:          uint64(id),
		Title:       title,
		Description: description,
		Poster:      poster,
		Reward:      reward,
		Status:      StatusOpen,
		ClaimWindow: claimWindow,
		CreatedAt:   now,
	}
	b.log(now, poster, "posted", "")
	bd.bounties.Set(id.Binary(), b)

	bd.escrowed += reward
	bd.statsOf(poster).Posted++
	return b, nil
}

// Claim reserves an open bounty for hunter for the bounty's claim window.
func (bd *Board) Claim(id uint64, hunter address, now time.Time) (*Bounty, error) {
	b, err := bd.mustGet(id)
	if err != nil {
		return nil, err
	}
	if !hunter.IsValid() {
		return nil, ErrInvalidCaller
	}
	if b.Status != StatusOpen {
		return nil, ErrNotOpen
	}
	if hunter == b.Poster {
		return nil, ErrOwnBounty
	}
	b.Status = StatusClaimed
	b.Hunter = hunter
	b.Proof = ""
	b.ClaimedAt = now
	b.log(now, hunter, "claimed", "")
	bd.statsOf(hunter) // make the hunter show up on the board
	return b, nil
}

// Unclaim lets the current hunter give a claimed bounty back voluntarily
// (counts as abandoned, but frees the task for others right away).
func (bd *Board) Unclaim(id uint64, hunter address, now time.Time) (*Bounty, error) {
	b, err := bd.mustGet(id)
	if err != nil {
		return nil, err
	}
	if b.Status != StatusClaimed {
		return nil, ErrNotClaimed
	}
	if hunter != b.Hunter {
		return nil, ErrNotHunter
	}
	bd.reopen(b, hunter, "released", "given back by hunter", now)
	bd.statsOf(hunter).Abandoned++
	return b, nil
}

// Release reopens a bounty whose claim window expired without a submission.
// Anyone may call it.
func (bd *Board) Release(id uint64, caller address, now time.Time) (*Bounty, error) {
	b, err := bd.mustGet(id)
	if err != nil {
		return nil, err
	}
	if b.Status != StatusClaimed {
		return nil, ErrNotClaimed
	}
	if !b.ClaimExpired(now) {
		return nil, ErrClaimActive
	}
	bd.statsOf(b.Hunter).Abandoned++
	bd.reopen(b, caller, "released", "claim expired", now)
	return b, nil
}

// Submit records the hunter's proof of work. Submitting again before review
// replaces the proof.
func (bd *Board) Submit(id uint64, hunter address, proof string, now time.Time) (*Bounty, error) {
	b, err := bd.mustGet(id)
	if err != nil {
		return nil, err
	}
	if b.Status != StatusClaimed && b.Status != StatusSubmitted {
		return nil, ErrNotClaimed
	}
	if hunter != b.Hunter {
		return nil, ErrNotHunter
	}
	if b.Status == StatusClaimed && b.ClaimExpired(now) {
		return nil, ErrClaimExpired
	}
	proof = strings.TrimSpace(proof)
	if len(proof) == 0 || len(proof) > MaxProofLen {
		return nil, ErrBadProof
	}
	b.Status = StatusSubmitted
	b.Proof = proof
	b.SubmittedAt = now
	b.log(now, hunter, "submitted", proof)
	return b, nil
}

// Approve accepts the submission. The owning realm must pay b.Reward to
// b.Hunter after a successful call.
func (bd *Board) Approve(id uint64, poster address, now time.Time) (*Bounty, error) {
	b, err := bd.mustGet(id)
	if err != nil {
		return nil, err
	}
	if b.Status != StatusSubmitted {
		return nil, ErrNotSubmitted
	}
	if poster != b.Poster {
		return nil, ErrNotPoster
	}
	bd.settle(b, poster, "paid", now)
	return b, nil
}

// Collect lets the hunter take the reward when the poster did not review the
// submission within the board's review window. The owning realm must pay
// b.Reward to b.Hunter after a successful call.
func (bd *Board) Collect(id uint64, hunter address, now time.Time) (*Bounty, error) {
	b, err := bd.mustGet(id)
	if err != nil {
		return nil, err
	}
	if b.Status != StatusSubmitted {
		return nil, ErrNotSubmitted
	}
	if hunter != b.Hunter {
		return nil, ErrNotHunter
	}
	if !now.After(bd.ReviewDeadline(b)) {
		return nil, ErrReviewActive
	}
	bd.settle(b, hunter, "auto-paid", now)
	return b, nil
}

// Reject declines the submission and reopens the bounty for everyone.
func (bd *Board) Reject(id uint64, poster address, reason string, now time.Time) (*Bounty, error) {
	b, err := bd.mustGet(id)
	if err != nil {
		return nil, err
	}
	if b.Status != StatusSubmitted {
		return nil, ErrNotSubmitted
	}
	if poster != b.Poster {
		return nil, ErrNotPoster
	}
	reason = strings.TrimSpace(reason)
	if len(reason) > MaxNoteLen {
		return nil, ErrBadNote
	}
	bd.statsOf(b.Hunter).Rejected++
	bd.statsOf(poster).RejectionsMade++
	bd.reopen(b, poster, "rejected", reason, now)
	return b, nil
}

// Cancel withdraws an open bounty. The owning realm must refund b.Reward to
// b.Poster after a successful call.
func (bd *Board) Cancel(id uint64, poster address, now time.Time) (*Bounty, error) {
	b, err := bd.mustGet(id)
	if err != nil {
		return nil, err
	}
	if b.Status != StatusOpen {
		return nil, ErrNotOpen
	}
	if poster != b.Poster {
		return nil, ErrNotPoster
	}
	b.Status = StatusCancelled
	b.ClosedAt = now
	b.log(now, poster, "cancelled", "")
	bd.escrowed -= b.Reward
	bd.statsOf(poster).Cancelled++
	return b, nil
}

// Get returns a bounty by id.
func (bd *Board) Get(id uint64) (*Bounty, bool) {
	v := bd.bounties.Get(seqid.ID(id).Binary())
	if v == nil {
		return nil, false
	}
	return v.(*Bounty), true
}

// Filter selects bounties for List. A nil Filter matches everything.
type Filter func(b *Bounty) bool

// ByStatus matches bounties in one of the given states.
func ByStatus(states ...Status) Filter {
	return func(b *Bounty) bool {
		for _, s := range states {
			if b.Status == s {
				return true
			}
		}
		return false
	}
}

// ByAddress matches bounties posted or hunted by addr.
func ByAddress(addr address) Filter {
	return func(b *Bounty) bool { return b.Poster == addr || b.Hunter == addr }
}

// List returns up to limit bounties matching f, newest first, skipping the
// first offset matches. It also returns the total number of matches.
func (bd *Board) List(f Filter, offset, limit int) (page []*Bounty, total int) {
	bd.bounties.ReverseIterate("", "", func(_ string, v any) bool {
		b := v.(*Bounty)
		if f != nil && !f(b) {
			return false
		}
		if total >= offset && len(page) < limit {
			page = append(page, b)
		}
		total++
		return false
	})
	return page, total
}

// Count returns how many bounties match f.
func (bd *Board) Count(f Filter) int {
	_, total := bd.List(f, 0, 0)
	return total
}

// Stats returns the reputation of addr (zero Stats if unknown).
func (bd *Board) Stats(addr address) Stats {
	v := bd.stats.Get(addr.String())
	if v == nil {
		return Stats{Address: addr}
	}
	return *(v.(*Stats))
}

// Participants is the number of distinct addresses that posted or claimed.
func (bd *Board) Participants() int { return bd.stats.Size() }

// Leaderboard returns the top n hunters by Score, then by Earned.
func (bd *Board) Leaderboard(n int) []Stats {
	var top []Stats
	bd.stats.Iterate("", "", func(_ string, v any) bool {
		s := *(v.(*Stats))
		if s.Completed == 0 {
			return false
		}
		// insertion into a small sorted slice
		i := len(top)
		for i > 0 && better(s, top[i-1]) {
			i--
		}
		if i >= n {
			return false
		}
		top = append(top, Stats{})
		copy(top[i+1:], top[i:])
		top[i] = s
		if len(top) > n {
			top = top[:n]
		}
		return false
	})
	return top
}

func better(a, b Stats) bool {
	if a.Score() != b.Score() {
		return a.Score() > b.Score()
	}
	return a.Earned > b.Earned
}

func (bd *Board) mustGet(id uint64) (*Bounty, error) {
	b, ok := bd.Get(id)
	if !ok {
		return nil, ErrNotFound
	}
	return b, nil
}

func (bd *Board) statsOf(addr address) *Stats {
	key := addr.String()
	if v := bd.stats.Get(key); v != nil {
		return v.(*Stats)
	}
	s := &Stats{Address: addr}
	bd.stats.Set(key, s)
	return s
}

func (bd *Board) reopen(b *Bounty, actor address, action, note string, now time.Time) {
	b.Status = StatusOpen
	b.Hunter = address("")
	b.ClaimedAt = time.Time{}
	b.SubmittedAt = time.Time{}
	b.log(now, actor, action, note)
}

func (bd *Board) settle(b *Bounty, actor address, action string, now time.Time) {
	b.Status = StatusPaid
	b.ClosedAt = now
	b.log(now, actor, action, "")
	bd.escrowed -= b.Reward
	bd.paid += b.Reward

	h := bd.statsOf(b.Hunter)
	h.Completed++
	h.Earned += b.Reward
	bd.statsOf(b.Poster).PaidOut += b.Reward
}

// Package bounty is a reusable, escrow-agnostic bounty board for Gno realms.
//
// A Board keeps bounties and per-address reputation. It never touches coins:
// the realm that owns the Board holds the escrow and pays out whatever the
// Board tells it to (see Approve, Collect and Cancel return values). This keeps
// the package pure and lets any realm (a DAO, a project treasury, a game)
// embed its own bounty board with a few lines of code.
//
// Lifecycle:
//
//	Open ──Claim──▶ Claimed ──Submit──▶ Submitted ──Approve/Collect──▶ Paid
//	 ▲  │             │                     │
//	 │  └─Cancel─▶ Cancelled                │
//	 └──────Release (claim expired)─────────┘◀──Reject
//
// All methods take the acting address and the current time explicitly, so the
// owning realm decides who is acting (usually cur.Previous().Address()) and
// tests can control the clock.
package bounty

import (
	"time"
)

// Status is the lifecycle state of a bounty.
type Status int

const (
	StatusOpen Status = iota
	StatusClaimed
	StatusSubmitted
	StatusPaid
	StatusCancelled
)

// String returns a human-readable status name.
func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusClaimed:
		return "claimed"
	case StatusSubmitted:
		return "submitted"
	case StatusPaid:
		return "paid"
	case StatusCancelled:
		return "cancelled"
	}
	return "unknown"
}

// ParseStatus is the inverse of Status.String. ok is false for unknown names.
func ParseStatus(s string) (st Status, ok bool) {
	switch s {
	case "open":
		return StatusOpen, true
	case "claimed":
		return StatusClaimed, true
	case "submitted":
		return StatusSubmitted, true
	case "paid":
		return StatusPaid, true
	case "cancelled":
		return StatusCancelled, true
	}
	return StatusOpen, false
}

// Event is one entry in a bounty's history.
type Event struct {
	At     time.Time
	Actor  address
	Action string // posted, claimed, submitted, rejected, released, paid, auto-paid, cancelled
	Note   string
}

// Bounty is a single task with a reward held in escrow by the owning realm.
type Bounty struct {
	ID          uint64
	Title       string
	Description string
	Poster      address
	Reward      int64 // in the smallest unit of the realm's denom (e.g. ugnot)

	Status      Status
	Hunter      address // zero when open
	Proof       string  // latest submission (link, PR, tx hash …)
	ClaimWindow time.Duration

	CreatedAt   time.Time
	ClaimedAt   time.Time
	SubmittedAt time.Time
	ClosedAt    time.Time

	History []Event
}

// ClaimDeadline is the time by which the current hunter must submit.
func (b *Bounty) ClaimDeadline() time.Time {
	return b.ClaimedAt.Add(b.ClaimWindow)
}

// ClaimExpired reports whether a claimed bounty can be released again.
func (b *Bounty) ClaimExpired(now time.Time) bool {
	return b.Status == StatusClaimed && now.After(b.ClaimDeadline())
}

func (b *Bounty) log(at time.Time, actor address, action, note string) {
	b.History = append(b.History, Event{At: at, Actor: actor, Action: action, Note: note})
}

// Stats is the public reputation of an address on one board.
type Stats struct {
	Address address

	// As hunter
	Completed int   // submissions approved (or auto-approved)
	Earned    int64 // total rewards received
	Rejected  int   // submissions rejected by posters
	Abandoned int   // claims that expired without a submission

	// As poster
	Posted         int   // bounties posted
	PaidOut        int64 // total rewards paid out
	RejectionsMade int   // submissions this poster rejected
	Cancelled      int   // bounties this poster cancelled
}

// Score is a simple reputation score used for the leaderboard:
// completed work counts, abandoned claims and rejected work cost a bit.
func (s *Stats) Score() int {
	score := s.Completed*10 - s.Abandoned*3 - s.Rejected*2
	if score < 0 {
		return 0
	}
	return score
}

// Package barkeep is a trustless bounty board on Gno.land.
//
// Post a task with a GNOT reward attached, a hunter claims it, submits proof,
// and the realm pays out when the poster approves. Rewards sit in this realm's
// escrow the whole time: there is no admin key and nobody can move them except
// through the rules below.
//
//   - Post:    send the reward (ugnot) with the call; it is locked in escrow.
//   - Claim:   reserve an open bounty for its claim window.
//   - Submit:  hand in a link/PR/tx as proof.
//   - Approve: poster accepts; the hunter is paid immediately.
//   - Reject:  poster declines; the bounty reopens for everyone.
//   - Collect: if the poster ghosts for the review window, the hunter can take the reward.
//   - Release: anyone can reopen a bounty whose claim expired.
//   - Unclaim: the hunter gives the bounty back.
//   - Cancel:  poster withdraws an open bounty and gets a full refund.
//
// The board logic lives in the reusable pure package gno.land/p/g1vx95s9pfwpg2flkw6x8z35546espgqemks8zkm/bounty/v0.
package barkeep

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/g1vx95s9pfwpg2flkw6x8z35546espgqemks8zkm/bounty/v0"
)

const denom = "ugnot"

var board = bounty.NewBoard(bounty.Config{
	MinReward:      1_000_000, // 1 GNOT
	MinClaimWindow: time.Hour,
	MaxClaimWindow: 30 * 24 * time.Hour,
	ReviewWindow:   72 * time.Hour,
})

// Post creates a bounty. Attach the reward as ugnot (e.g. -send 5000000ugnot
// for 5 GNOT). claimHours is how long a hunter has to deliver after claiming.
func Post(cur realm, title, description string, claimHours int) uint64 {
	// Only a direct user call (wallet / gnokey maketx call) carries the coins
	// to this realm, so only then does OriginSend describe what we received.
	if !cur.Previous().IsUserCall() {
		panic("barkeep: Post must be called directly by a user wallet")
	}
	poster := cur.Previous().Address()
	reward := receivedReward()

	b, err := board.Post(poster, title, description, reward, hours(claimHours), time.Now())
	check(err)
	chain.Emit("BountyPosted",
		"id", idStr(b.ID),
		"poster", poster.String(),
		"reward", strconv.FormatInt(reward, 10),
	)
	return b.ID
}

// Claim reserves an open bounty for the caller.
func Claim(cur realm, id uint64) {
	assertNoSend(cur)
	hunter := cur.Previous().Address()
	b, err := board.Claim(id, hunter, time.Now())
	check(err)
	chain.Emit("BountyClaimed", "id", idStr(b.ID), "hunter", hunter.String())
}

// Unclaim gives a claimed bounty back so others can take it.
func Unclaim(cur realm, id uint64) {
	assertNoSend(cur)
	hunter := cur.Previous().Address()
	b, err := board.Unclaim(id, hunter, time.Now())
	check(err)
	chain.Emit("BountyReleased", "id", idStr(b.ID), "by", hunter.String())
}

// Submit hands in proof of work (a URL, PR, tx hash …, max 280 chars).
func Submit(cur realm, id uint64, proof string) {
	assertNoSend(cur)
	hunter := cur.Previous().Address()
	b, err := board.Submit(id, hunter, proof, time.Now())
	check(err)
	chain.Emit("BountySubmitted", "id", idStr(b.ID), "hunter", hunter.String())
}

// Approve accepts the submission and pays the hunter from escrow.
func Approve(cur realm, id uint64) {
	assertNoSend(cur)
	poster := cur.Previous().Address()
	b, err := board.Approve(id, poster, time.Now())
	check(err)
	payout(cur, b.Hunter, b.Reward)
	chain.Emit("BountyPaid", "id", idStr(b.ID), "hunter", b.Hunter.String(),
		"reward", strconv.FormatInt(b.Reward, 10))
}

// Reject declines the submission; the bounty reopens for everyone.
func Reject(cur realm, id uint64, reason string) {
	assertNoSend(cur)
	poster := cur.Previous().Address()
	b, err := board.Reject(id, poster, reason, time.Now())
	check(err)
	chain.Emit("BountyRejected", "id", idStr(b.ID))
}

// Collect pays the hunter when the poster did not review the submission
// within the review window (72h).
func Collect(cur realm, id uint64) {
	assertNoSend(cur)
	hunter := cur.Previous().Address()
	b, err := board.Collect(id, hunter, time.Now())
	check(err)
	payout(cur, b.Hunter, b.Reward)
	chain.Emit("BountyPaid", "id", idStr(b.ID), "hunter", b.Hunter.String(),
		"reward", strconv.FormatInt(b.Reward, 10), "auto", "true")
}

// Release reopens a bounty whose claim window expired. Anyone can call it.
func Release(cur realm, id uint64) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	b, err := board.Release(id, caller, time.Now())
	check(err)
	chain.Emit("BountyReleased", "id", idStr(b.ID), "by", caller.String())
}

// Cancel withdraws an open bounty and refunds the reward to the poster.
func Cancel(cur realm, id uint64) {
	assertNoSend(cur)
	poster := cur.Previous().Address()
	b, err := board.Cancel(id, poster, time.Now())
	check(err)
	payout(cur, b.Poster, b.Reward)
	chain.Emit("BountyCancelled", "id", idStr(b.ID))
}

// --- read-only helpers (usable by other realms and clients) ---

// GetBounty returns a copy of a bounty's main fields.
func GetBounty(id uint64) (title string, poster address, reward int64, status string, hunter address) {
	b, ok := board.Get(id)
	if !ok {
		panic(bounty.ErrNotFound.Error())
	}
	return b.Title, b.Poster, b.Reward, b.Status.String(), b.Hunter
}

// Reputation returns the hunter stats of addr.
func Reputation(addr address) (completed int, earned int64, score int) {
	s := board.Stats(addr)
	return s.Completed, s.Earned, s.Score()
}

// Escrowed is the total ugnot currently locked for open bounties.
func Escrowed() int64 { return board.Escrowed() }

// --- internals ---

func payout(cur realm, to address, amount int64) {
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), to, chain.Coins{{denom, amount}})
}

// receivedReward returns the ugnot attached to the call and refuses any
// other denom (the transaction reverts, so nothing gets stuck).
func receivedReward() int64 {
	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != denom {
			panic("barkeep: only " + denom + " can be used as a reward")
		}
	}
	amount := sent.AmountOf(denom)
	if amount <= 0 {
		panic("barkeep: attach the reward as ugnot, e.g. 5000000ugnot for 5 GNOT")
	}
	return amount
}

func assertNoSend(cur realm) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("barkeep: this function does not take coins")
	}
}

func hours(h int) time.Duration {
	if h <= 0 || h > 24*365 {
		panic(bounty.ErrBadWindow.Error())
	}
	return time.Duration(h) * time.Hour
}

func check(err error) {
	if err != nil {
		panic(err.Error())
	}
}

func idStr(id uint64) string { return strconv.FormatUint(id, 10) }

package barkeep

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1vx95s9pfwpg2flkw6x8z35546espgqemks8zkm/bounty/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/ufmt/v0"
)

const pageSize = 10

// Render draws the tavern notice board in gnoweb.
//
//	""               notice board (open bounties)
//	"status/{s}"     filter: open, claimed, submitted, paid, cancelled, all
//	"bounty/{id}"    bounty details, history and context actions
//	"hunters"        leaderboard
//	"u/{addr}"       profile of an address
//	"help"           how it works
func Render(path string) string {
	r := mux.NewRouter()
	r.HandleFunc("", renderBoard)
	r.HandleFunc("status/{status}", renderBoard)
	r.HandleFunc("bounty/{id}", renderBounty)
	r.HandleFunc("hunters", renderHunters)
	r.HandleFunc("u/{addr}", renderProfile)
	r.HandleFunc("help", renderHelp)
	r.NotFoundHandler = func(res *mux.ResponseWriter, _ *mux.Request) {
		res.Write(header() + "> The barkeep shrugs. Nothing pinned here.\n\n[Back to the board](" + link("") + ")\n")
	}
	return r.Render(path)
}

// --- pages ---

func renderBoard(res *mux.ResponseWriter, req *mux.Request) {
	statusName := req.GetVar("status")
	if statusName == "" {
		statusName = "open"
	}
	var filter bounty.Filter
	if statusName != "all" {
		st, ok := bounty.ParseStatus(statusName)
		if !ok {
			res.Write(header() + "> Unknown filter.\n")
			return
		}
		filter = bounty.ByStatus(st)
	}

	page := pageParam(req)
	items, total := board.List(filter, (page-1)*pageSize, pageSize)

	var sb strings.Builder
	sb.WriteString(header())
	sb.WriteString(statsLine())
	sb.WriteString("\n" + postButton() + "\n\n")
	sb.WriteString(tabs(statusName) + "\n\n")

	if total == 0 {
		sb.WriteString("_The board is empty here. Pull up a stool and post the first bounty._\n")
	}
	for _, b := range items {
		sb.WriteString(card(b))
	}
	sb.WriteString(pager(req, page, total))
	sb.WriteString(footer())
	res.Write(sb.String())
}

func renderBounty(res *mux.ResponseWriter, req *mux.Request) {
	id, err := strconv.ParseUint(req.GetVar("id"), 10, 64)
	b, ok := board.Get(id)
	if err != nil || !ok {
		res.Write(header() + "> No bounty with that number.\n\n[Back to the board](" + link("") + ")\n")
		return
	}
	now := time.Now()

	var sb strings.Builder
	sb.WriteString("[← Back to the board](" + link("") + ")\n\n")
	sb.WriteString(ufmt.Sprintf("# #%d · %s\n\n", b.ID, sanitize.InlineText(b.Title)))
	sb.WriteString(ufmt.Sprintf("**%s** · %s · claim window %s\n\n", gnot(b.Reward), badge(b.Status), dur(b.ClaimWindow)))

	if b.Description != "" {
		sb.WriteString(sanitize.Blockquote(b.Description) + "\n\n")
	}

	sb.WriteString("| | |\n|---|---|\n")
	sb.WriteString("| Poster | " + who(b.Poster) + " |\n")
	sb.WriteString("| Posted | " + ts(b.CreatedAt) + " |\n")
	switch b.Status {
	case bounty.StatusClaimed:
		sb.WriteString("| Hunter | " + who(b.Hunter) + " |\n")
		sb.WriteString("| Deliver by | " + ts(b.ClaimDeadline()) + " (" + left(now, b.ClaimDeadline()) + ") |\n")
	case bounty.StatusSubmitted:
		sb.WriteString("| Hunter | " + who(b.Hunter) + " |\n")
		sb.WriteString("| Proof | " + proof(b.Proof) + " |\n")
		sb.WriteString("| Review by | " + ts(board.ReviewDeadline(b)) + " (" + left(now, board.ReviewDeadline(b)) + ") |\n")
	case bounty.StatusPaid:
		sb.WriteString("| Paid to | " + who(b.Hunter) + " |\n")
		sb.WriteString("| Proof | " + proof(b.Proof) + " |\n")
		sb.WriteString("| Closed | " + ts(b.ClosedAt) + " |\n")
	case bounty.StatusCancelled:
		sb.WriteString("| Closed | " + ts(b.ClosedAt) + " |\n")
	}

	sb.WriteString("\n## What can happen next\n\n")
	sb.WriteString(actions(b, now))

	sb.WriteString("\n## History\n\n| When | Who | What | Note |\n|---|---|---|---|\n")
	for i := len(b.History) - 1; i >= 0; i-- {
		e := b.History[i]
		sb.WriteString("| " + ts(e.At) + " | " + who(e.Actor) + " | " + e.Action + " | " + sanitize.TableCell(e.Note) + " |\n")
	}
	sb.WriteString(footer())
	res.Write(sb.String())
}

func renderHunters(res *mux.ResponseWriter, _ *mux.Request) {
	var sb strings.Builder
	sb.WriteString(header())
	sb.WriteString("## 🏆 Hall of Hunters\n\n")
	top := board.Leaderboard(25)
	if len(top) == 0 {
		sb.WriteString("_No bounty has been paid yet. Be the first legend of the tavern._\n")
	} else {
		sb.WriteString("| # | Hunter | Score | Done | Earned | Rejected | Abandoned |\n|---|---|---|---|---|---|---|\n")
		for i, s := range top {
			sb.WriteString(ufmt.Sprintf("| %d %s | %s | %d | %d | %s | %d | %d |\n",
				i+1, medal(i), who(s.Address), s.Score(), s.Completed, gnot(s.Earned), s.Rejected, s.Abandoned))
		}
		sb.WriteString("\n_Score = 10 per completed bounty − 3 per abandoned claim − 2 per rejected submission._\n")
	}
	sb.WriteString(footer())
	res.Write(sb.String())
}

func renderProfile(res *mux.ResponseWriter, req *mux.Request) {
	addr := address(req.GetVar("addr"))
	if !addr.IsValid() {
		res.Write(header() + "> That is not a valid address.\n")
		return
	}
	s := board.Stats(addr)

	var sb strings.Builder
	sb.WriteString("[← Back to the board](" + link("") + ")\n\n")
	sb.WriteString("# 🧙 " + short(addr) + "\n\n`" + addr.String() + "`\n\n")
	sb.WriteString("| As hunter | | As poster | |\n|---|---|---|---|\n")
	sb.WriteString(ufmt.Sprintf("| Score | **%d** | Posted | %d |\n", s.Score(), s.Posted))
	sb.WriteString(ufmt.Sprintf("| Completed | %d | Paid out | %s |\n", s.Completed, gnot(s.PaidOut)))
	sb.WriteString(ufmt.Sprintf("| Earned | %s | Rejections made | %d |\n", gnot(s.Earned), s.RejectionsMade))
	sb.WriteString(ufmt.Sprintf("| Rejected | %d | Cancelled | %d |\n", s.Rejected, s.Cancelled))
	sb.WriteString(ufmt.Sprintf("| Abandoned | %d | | |\n\n", s.Abandoned))

	items, total := board.List(bounty.ByAddress(addr), 0, 20)
	sb.WriteString(ufmt.Sprintf("## Bounties (%d)\n\n", total))
	for _, b := range items {
		sb.WriteString(card(b))
	}
	sb.WriteString(footer())
	res.Write(sb.String())
}

func renderHelp(res *mux.ResponseWriter, _ *mux.Request) {
	res.Write(header() + `## How the tavern works

1. **Post** a task and attach the reward in GNOT. The coins are locked in this realm's escrow, with no admin key.
2. A hunter **claims** it and has the claim window to deliver.
3. The hunter **submits** proof (a link, a PR, a tx hash).
4. You **approve** and the hunter is paid right away, or **reject** and the bounty goes back on the board.

**Fair play rules**

- Didn't review a submission within **72 hours**? The hunter can **collect** the reward.
- A hunter didn't deliver in time? **Anyone** can **release** the claim so others can take it.
- Changed your mind? **Cancel** an open bounty and get a full refund.
- Every rejection, abandoned claim and payout is public, on both sides.

**For builders:** the board logic is the pure package ` + "`gno.land/p/g1vx95s9pfwpg2flkw6x8z35546espgqemks8zkm/bounty/v0`" + `. Import it to give your DAO, game or project its own bounty board.

[Back to the board](` + link("") + `)
` + footer())
}

// --- building blocks ---

func header() string {
	return "# 🍺 Barkeep\n\n_The tavern notice board of Gno.land: post a task, put GNOT on it, pay whoever gets it done._\n\n"
}

func footer() string {
	return "\n---\n\n[Board](" + link("") + ") · [Hall of Hunters](" + link("hunters") + ") · [How it works](" + link("help") + ")\n"
}

func statsLine() string {
	open := board.Count(bounty.ByStatus(bounty.StatusOpen))
	working := board.Count(bounty.ByStatus(bounty.StatusClaimed, bounty.StatusSubmitted))
	return ufmt.Sprintf("**%d** open · **%d** in progress · **%s** in escrow · **%s** paid out · **%d** patrons\n",
		open, working, gnot(board.Escrowed()), gnot(board.TotalPaid()), board.Participants())
}

func postButton() string {
	url := txlink.NewLink("Post").
		AddArgs("title", "", "description", "", "claimHours", "48").
		SetSend("5000000ugnot").
		URL()
	return "[📌 Pin a new bounty](" + url + ")"
}

func tabs(active string) string {
	names := []string{"open", "claimed", "submitted", "paid", "cancelled", "all"}
	labels := []string{"Open", "Claimed", "In review", "Paid", "Cancelled", "All"}
	var parts []string
	for i, n := range names {
		if n == active {
			parts = append(parts, "**"+labels[i]+"**")
		} else {
			parts = append(parts, "["+labels[i]+"]("+link("status/"+n)+")")
		}
	}
	return strings.Join(parts, " · ")
}

func card(b *bounty.Bounty) string {
	line := ufmt.Sprintf("### [#%d %s](%s)\n\n**%s** · %s · by %s",
		b.ID, sanitize.InlineText(b.Title), link("bounty/"+idStr(b.ID)), gnot(b.Reward), badge(b.Status), who(b.Poster))
	if b.Hunter != "" {
		line += " · hunter " + who(b.Hunter)
	}
	return line + "\n\n"
}

func actions(b *bounty.Bounty, now time.Time) string {
	id := idStr(b.ID)
	var out []string
	add := func(label, fn, note string, args ...string) {
		all := append([]string{"id", id}, args...)
		out = append(out, "- ["+label+"]("+txlink.NewLink(fn).AddArgs(all...).URL()+") "+note)
	}

	switch b.Status {
	case bounty.StatusOpen:
		add("🗡️ Claim this bounty", "Claim", "– you get "+dur(b.ClaimWindow)+" to deliver.")
		add("✖️ Cancel & refund", "Cancel", "– poster only.")
	case bounty.StatusClaimed:
		add("📜 Submit proof", "Submit", "– hunter only.", "proof", "")
		add("↩️ Give it back", "Unclaim", "– hunter only.")
		if b.ClaimExpired(now) {
			add("⏰ Release expired claim", "Release", "– anyone, the claim window is over.")
		}
	case bounty.StatusSubmitted:
		add("✅ Approve & pay", "Approve", "– poster only, pays "+gnot(b.Reward)+".")
		add("❌ Reject", "Reject", "– poster only, reopens the bounty.", "reason", "")
		add("📜 Update proof", "Submit", "– hunter only.", "proof", "")
		if now.After(board.ReviewDeadline(b)) {
			add("💰 Collect (poster did not review)", "Collect", "– hunter only.")
		}
	default:
		return "_This bounty is closed._\n"
	}
	return strings.Join(out, "\n") + "\n"
}

func pager(req *mux.Request, page, total int) string {
	pages := (total + pageSize - 1) / pageSize
	if pages <= 1 {
		return ""
	}
	base := req.Path
	s := "\n"
	if page > 1 {
		s += "[← newer](" + link(base) + "?page=" + strconv.Itoa(page-1) + ") "
	}
	s += ufmt.Sprintf("page %d of %d", page, pages)
	if page < pages {
		s += " [older →](" + link(base) + "?page=" + strconv.Itoa(page+1) + ")"
	}
	return s + "\n"
}

func pageParam(req *mux.Request) int {
	p, err := strconv.Atoi(req.Query.Get("page"))
	if err != nil || p < 1 {
		return 1
	}
	return p
}

func badge(s bounty.Status) string {
	switch s {
	case bounty.StatusOpen:
		return "🟢 open"
	case bounty.StatusClaimed:
		return "🟡 claimed"
	case bounty.StatusSubmitted:
		return "🔵 in review"
	case bounty.StatusPaid:
		return "💰 paid"
	case bounty.StatusCancelled:
		return "⚪ cancelled"
	}
	return s.String()
}

func medal(i int) string {
	switch i {
	case 0:
		return "🥇"
	case 1:
		return "🥈"
	case 2:
		return "🥉"
	}
	return ""
}

func who(a address) string {
	if a == "" {
		return "–"
	}
	return "[" + short(a) + "](" + link("u/"+a.String()) + ")"
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:7] + "…" + s[len(s)-4:]
}

func proof(p string) string {
	if u := sanitize.URL(p); u != "" && (strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "http://")) {
		return "[" + sanitize.LinkTitle(p) + "](" + u + ")"
	}
	return sanitize.TableCell(p)
}

// link builds a path inside this realm, e.g. link("hunters") -> "/r/…/barkeep:hunters".
func link(sub string) string {
	if sub == "" {
		return realmURL()
	}
	return realmURL() + ":" + sub
}

func realmURL() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

// gnot formats ugnot as GNOT with up to 6 decimals, e.g. 1500000 -> "1.5 GNOT".
func gnot(u int64) string {
	whole := u / 1_000_000
	frac := u % 1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	fs := strconv.FormatInt(frac+1_000_000, 10)[1:] // zero-padded to 6 digits
	fs = strings.TrimRight(fs, "0")
	return strconv.FormatInt(whole, 10) + "." + fs + " GNOT"
}

func ts(t time.Time) string {
	if t.IsZero() {
		return "–"
	}
	return t.UTC().Format("2006-01-02 15:04 UTC")
}

func dur(d time.Duration) string {
	h := int(d / time.Hour)
	if h >= 48 && h%24 == 0 {
		return strconv.Itoa(h/24) + " days"
	}
	if h == 1 {
		return "1 hour"
	}
	return strconv.Itoa(h) + " hours"
}

func left(now, deadline time.Time) string {
	if now.After(deadline) {
		return "expired"
	}
	d := deadline.Sub(now)
	if d < time.Hour {
		return strconv.Itoa(int(d/time.Minute)) + " min left"
	}
	return dur(d.Truncate(time.Hour)) + " left"
}

package spike_probe

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nt/svg/v0"
)

// CubeState stores nine stickers per face in U, R, F, D, L, B order.
type CubeState [54]uint8

// ProbeRule is the interface used by the cross-realm ownership probe.
type ProbeRule interface {
	ID() string
	Check(steps int) error
}

func SolvedState() CubeState {
	var state CubeState
	for i := range state {
		state[i] = uint8(i / 9)
	}
	return state
}

// ApplyMovesKernel simulates per-move work with a cyclic permutation and six face cross checks.
func ApplyMovesKernel(n int) CubeState {
	state := SolvedState()
	offset := 1
	for step := 0; step < n; step++ {
		var next CubeState
		for i := range next {
			next[i] = state[(i+offset)%len(state)]
		}
		state = next

		// Each completed cross adds one to the next cyclic offset.
		offset = 1
		for face := 0; face < len(state)/9; face++ {
			start := face * 9
			center := state[start+4]
			if state[start+1] == center && state[start+3] == center &&
				state[start+5] == center && state[start+7] == center {
				offset++
			}
		}
	}
	return state
}

func CommitHash(domain, roundKey, caller, payload, salt string) string {
	preimage := lengthPrefix(domain) + "|" + lengthPrefix(roundKey) + "|" +
		lengthPrefix(caller) + "|" + lengthPrefix(payload) + "|" + lengthPrefix(salt)
	hash := sha256.Sum256([]byte(preimage))
	return hex.EncodeToString(hash[:])
}

func lengthPrefix(s string) string {
	return strconv.Itoa(len(s)) + ":" + s
}

// EscapeJSONString escapes the contents of a JSON string, excluding the enclosing quotes.
func EscapeJSONString(s string) string {
	const digits = "0123456789abcdef"
	var escaped strings.Builder
	for i := 0; i < len(s); i++ {
		b := s[i]
		switch b {
		case '"', '\\':
			escaped.WriteByte('\\')
			escaped.WriteByte(b)
		case '\b':
			escaped.WriteString(`\b`)
		case '\f':
			escaped.WriteString(`\f`)
		case '\n':
			escaped.WriteString(`\n`)
		case '\r':
			escaped.WriteString(`\r`)
		case '\t':
			escaped.WriteString(`\t`)
		default:
			if b < 0x20 {
				escaped.WriteString(`\u00`)
				escaped.WriteByte(digits[b>>4])
				escaped.WriteByte(digits[b&0x0f])
			} else {
				escaped.WriteByte(b)
			}
		}
	}
	return escaped.String()
}

func RenderNetMarkdown(c CubeState, alt string) string {
	const stickerSize = 12
	const faceSize = 3 * stickerSize
	const width, height = 4 * faceSize, 3 * faceSize
	canvas := svg.NewCanvas(width, height).WithViewBox(0, 0, width, height)

	facePositions := [6][2]int{{1, 0}, {2, 1}, {1, 1}, {1, 2}, {0, 1}, {3, 1}}
	colors := [6]string{"#f5f5f5", "#b91c1c", "#15803d", "#facc15", "#f97316", "#1d4ed8"}
	for i, color := range c {
		face := facePositions[i/9]
		sticker := i % 9
		x := face[0]*faceSize + sticker%3*stickerSize
		y := face[1]*faceSize + sticker/3*stickerSize
		fill := "#6b7280"
		if int(color) < len(colors) {
			fill = colors[color]
		}
		canvas.Append(svg.NewRectangle(x, y, stickerSize-1, stickerSize-1, fill))
	}
	return canvas.Render(alt)
}

