package gun

import (
	"chain"
	"chain/banker"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g1k0pgsw39lh0a6mama0qh0lxa6vphd4yc2w9gqw/rosca"
)

const (
	pkgPath = "gno.land/r/g1k0pgsw39lh0a6mama0qh0lxa6vphd4yc2w9gqw/gun"
	self    = "/r/g1k0pgsw39lh0a6mama0qh0lxa6vphd4yc2w9gqw/gun"
	perPage = 10
)

// Render shows the circles. Paths: "" (home, ?page=N), "c/<id>" (one
// circle), "u/<address>" (one member's circles).
func Render(path string) string {
	route, query := path, ""
	if i := strings.Index(path, "?"); i >= 0 {
		route, query = path[:i], path[i+1:]
	}
	switch {
	case route == "":
		return renderHome(pageParam(query))
	case strings.HasPrefix(route, "c/"):
		id, err := strconv.Atoi(route[2:])
		if err != nil {
			return notFound()
		}
		c, ok := get(id)
		if !ok {
			return notFound()
		}
		return renderCircle(id, c)
	case strings.HasPrefix(route, "u/"):
		a := address(route[2:])
		if !a.IsValid() {
			return notFound()
		}
		return renderMember(a)
	}
	return notFound()
}

func notFound() string {
	return "# Not found\n\n[Back to all circles](" + self + ")\n"
}

func pageParam(query string) int {
	for _, kv := range strings.Split(query, "&") {
		if strings.HasPrefix(kv, "page=") {
			if n, err := strconv.Atoi(kv[5:]); err == nil && n > 0 && n < 1_000_000 {
				return n
			}
		}
	}
	return 1
}

func renderHome(page int) string {
	var b strings.Builder
	b.WriteString("# Gün: savings circles on gno.land\n\n")
	b.WriteString("_Altın günü, on chain._ A group of friends pays the same amount every round, ")
	b.WriteString("and each round the whole pot goes to one of them, in turn, until everyone has had it once. ")
	b.WriteString("It is how millions of people save without a bank: the *altın günü* in Turkey, ")
	b.WriteString("the *tanda* in Mexico, the *susu* in West Africa, the *hui* in China.\n\n")
	b.WriteString("This realm holds the coins and keeps the books in the open, so nobody has to trust the organizer:\n\n")
	b.WriteString("- **Everyone joins on purpose.** The organizer lists the members; each one joins by locking their collateral.\n")
	b.WriteString("- **Collateral covers missed payments.** Each member locks a number of contributions up front. ")
	b.WriteString("With *members − 1* of them the circle is fully secured: every member is guaranteed the full pot.\n")
	b.WriteString("- **Payouts are pulled, not pushed.** Pots, refunds and released collateral are credited, and their owner withdraws them.\n")
	b.WriteString("- **Late is visible.** Every payment is marked on time, late or covered, round by round.\n\n")
	b.WriteString("[Start a circle](" + self + "$help&func=Create) · ")
	b.WriteString("[How the rules work](" + self + "$source)\n\n")

	total := circles.Size()
	b.WriteString("## Circles\n\n")
	if total == 0 {
		b.WriteString("No circles yet.\n\n")
	} else {
		pages := (total + perPage - 1) / perPage
		if page > pages {
			page = pages
		}
		b.WriteString("| # | Name | Members | Contribution | Status |\n|---|---|---|---|---|\n")
		offset := (page - 1) * perPage
		circles.ReverseIterateByOffset(offset, perPage, func(k string, v any) bool {
			c := v.(*rosca.Circle)
			id, _ := strconv.Atoi(strings.TrimLeft(k, "0"))
			b.WriteString(ufmt.Sprintf("| %d | [%s](%s:c/%d) | %d | %s | %s |\n",
				id, sanitize.InlineText(c.Name()), self, id, c.Size(),
				gnot(c.Contribution()), statusLine(c)))
			return false
		})
		if pages > 1 {
			b.WriteString("\n")
			if page > 1 {
				b.WriteString(ufmt.Sprintf("[← newer](%s:?page=%d) ", self, page-1))
			}
			b.WriteString(ufmt.Sprintf("page %d of %d", page, pages))
			if page < pages {
				b.WriteString(ufmt.Sprintf(" [older →](%s:?page=%d)", self, page+1))
			}
			b.WriteString("\n")
		}
	}
	b.WriteString("\n---\n\n")
	bal := banker.NewReadonlyBanker().GetCoin(chain.PackageAddress(pkgPath), denom)
	b.WriteString(ufmt.Sprintf("**Books.** The circles account for %s; the realm holds %s.", gnot(totalHeld), gnot(bal)))
	if bal < totalHeld {
		b.WriteString(" **The realm holds less than it owes. Please report this.**")
	}
	b.WriteString("\n")
	return b.String()
}

func renderCircle(id int, c *rosca.Circle) string {
	var b strings.Builder
	t := now()
	b.WriteString(ufmt.Sprintf("# %s\n\n", sanitize.InlineText(c.Name())))
	b.WriteString(ufmt.Sprintf("Circle #%d · **%s** · organized by %s\n\n", id, statusLine(c), who(c.Organizer())))

	b.WriteString(ufmt.Sprintf("- **Contribution:** %s per member per round\n", gnot(c.Contribution())))
	b.WriteString(ufmt.Sprintf("- **Pot:** %s to one member each round, %d rounds\n", gnot(c.Pot()), c.Size()))
	b.WriteString(ufmt.Sprintf("- **Round length:** %s\n", duration(c.Period())))
	b.WriteString(ufmt.Sprintf("- **Collateral:** %s per member (%d contributions). ", gnot(c.CollateralDue()), c.CollateralRounds()))
	switch {
	case c.FullySecured():
		b.WriteString("Fully secured: every member is guaranteed the full pot.\n")
	case c.CollateralRounds() == 0:
		b.WriteString("None: the circle runs on trust, and the first missed payment ends it.\n")
	default:
		b.WriteString(ufmt.Sprintf("Covers %d missed payments per member; one more ends the circle.\n", c.CollateralRounds()))
	}

	switch c.Status() {
	case rosca.Forming:
		b.WriteString(ufmt.Sprintf("- **Join by:** %s (%s)\n", when(c.JoinBy()), relative(c.JoinBy(), t)))
	case rosca.Active:
		due := c.DueAt()
		b.WriteString(ufmt.Sprintf("- **Round %d of %d** is due %s (%s). Recipient: %s\n",
			c.Round()+1, c.Size(), when(due), relative(due, t), who(c.Recipient(c.Round()))))
	default:
		b.WriteString(ufmt.Sprintf("- **Ended:** %s", when(c.EndedAt())))
		if c.Note() != "" {
			b.WriteString(" · " + c.Note())
		}
		b.WriteString("\n")
	}

	// Members, in turn order. Amounts in GNOT; columns that say nothing in
	// the current status are left out to keep the table readable.
	forming, active := c.Status() == rosca.Forming, c.Status() == rosca.Active
	b.WriteString("\n## Members\n\nAmounts in GNOT.\n\n| Turn | Member |")
	if forming {
		b.WriteString(" Joined |")
	}
	if active {
		b.WriteString(" This round |")
	}
	b.WriteString(" Paid in | Received | Locked | To withdraw |\n|---|---|")
	if forming {
		b.WriteString("---|")
	}
	if active {
		b.WriteString("---|")
	}
	b.WriteString("---|---|---|---|\n")
	for r := 0; r < c.Size(); r++ {
		a := c.Recipient(r)
		m, _ := c.MemberOf(a)
		turn := strconv.Itoa(r + 1)
		if active && r == c.Round() {
			turn = "**" + turn + " ◀**"
		}
		flags := ""
		if m.Defaulted {
			flags = " · defaulted"
		} else if m.Covered > 0 || m.Late > 0 {
			flags = ufmt.Sprintf(" · %d late, %d covered", m.Late, m.Covered)
		}
		b.WriteString(ufmt.Sprintf("| %s | %s%s |", turn, who(a), flags))
		if forming {
			if m.Joined {
				b.WriteString(" yes |")
			} else {
				b.WriteString(" not yet |")
			}
		}
		if active {
			b.WriteString(" " + markText(c.MarkOf(a)) + " |")
		}
		b.WriteString(ufmt.Sprintf(" %s | %s | %s | %s |\n",
			num(m.PaidIn), num(m.Received+m.Compensated), num(m.Collateral), num(m.Claimable)))
	}

	b.WriteString("\n## Actions\n\n")
	switch c.Status() {
	case rosca.Forming:
		b.WriteString(ufmt.Sprintf("- [Join](%s$help&func=Join&id=%d&.send=%dugnot): send exactly %s\n",
			self, id, c.CollateralDue(), gnot(c.CollateralDue())))
		b.WriteString(ufmt.Sprintf("- [Cancel](%s$help&func=Cancel&id=%d): organizer any time, anyone after the join window\n", self, id))
	case rosca.Active:
		b.WriteString(ufmt.Sprintf("- [Pay this round](%s$help&func=Pay&id=%d&.send=%dugnot): send exactly %s\n",
			self, id, c.Contribution(), gnot(c.Contribution())))
		if t > c.DueAt() {
			b.WriteString(ufmt.Sprintf("- [Settle](%s$help&func=Settle&id=%d): the round is overdue; anyone can close it\n", self, id))
		} else {
			b.WriteString(ufmt.Sprintf("- Settle: possible after %s\n", when(c.DueAt())))
		}
	}
	if c.Status() == rosca.Forming || c.Status() == rosca.Active {
		b.WriteString(ufmt.Sprintf("- [Propose a turn swap](%s$help&func=ProposeSwap&id=%d) · [accept one](%s$help&func=AcceptSwap&id=%d)\n",
			self, id, self, id))
	}
	b.WriteString(ufmt.Sprintf("- [Withdraw what you are owed](%s$help&func=Withdraw&id=%d)\n", self, id))

	h := c.History()
	if len(h) > 0 {
		b.WriteString("\n## Rounds\n\n")
		b.WriteString("Marks are per member in listed order: **P** on time · **L** late · **C** covered from collateral · **X** missed with no collateral.\n\n")
		b.WriteString("| Round | Recipient | Pot | Closed | Marks |\n|---|---|---|---|---|\n")
		for i, r := range h {
			pot := gnot(r.Pot)
			if r.Pot == 0 {
				pot = "not formed"
			}
			b.WriteString(ufmt.Sprintf("| %d | %s | %s | %s | `%s` |\n", i+1, who(r.Recipient), pot, when(r.ClosedAt), r.Marks))
		}
	}
	b.WriteString("\n[All circles](" + self + ")\n")
	return b.String()
}

func renderMember(a address) string {
	var b strings.Builder
	b.WriteString("# Circles of " + short(a) + "\n\n")
	v := byMember.Get(a.String())
	if v == nil {
		b.WriteString("Not in any circle yet. Circles show up here once you create or join them.\n")
	} else {
		b.WriteString("| # | Name | Status | Your turn | Withdrawable |\n|---|---|---|---|---|\n")
		ids := v.([]int)
		for i := len(ids) - 1; i >= 0; i-- {
			c, ok := get(ids[i])
			if !ok {
				continue
			}
			m, _ := c.MemberOf(a)
			b.WriteString(ufmt.Sprintf("| %d | [%s](%s:c/%d) | %s | %d of %d | %s |\n",
				ids[i], sanitize.InlineText(c.Name()), self, ids[i], statusLine(c),
				c.TurnOf(a)+1, c.Size(), gnot(m.Claimable)))
		}
	}
	b.WriteString("\n[All circles](" + self + ")\n")
	return b.String()
}

// ---------------------------------------------------------------- format

func statusLine(c *rosca.Circle) string {
	switch c.Status() {
	case rosca.Active:
		return ufmt.Sprintf("round %d of %d", c.Round()+1, c.Size())
	}
	return c.Status().String()
}

func markText(m rosca.Mark) string {
	switch m {
	case rosca.OnTime:
		return "paid"
	case rosca.Late:
		return "paid late"
	case rosca.Covered:
		return "covered"
	case rosca.Missed:
		return "missed"
	}
	return "not yet"
}

func who(a address) string {
	return ufmt.Sprintf("[%s](%s:u/%s)", short(a), self, a.String())
}

func short(a address) string {
	s := a.String()
	if len(s) < 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

// gnot formats ugnot as GNOT with the unit.
func gnot(u int64) string { return num(u) + " GNOT" }

// num formats ugnot as a GNOT amount, dropping trailing zeros.
func num(u int64) string {
	neg := u < 0
	if neg {
		u = -u
	}
	whole := strconv.FormatInt(u/1_000_000, 10)
	frac := strconv.FormatInt(u%1_000_000, 10)
	for len(frac) < 6 {
		frac = "0" + frac
	}
	frac = strings.TrimRight(frac, "0")
	s := whole
	if frac != "" {
		s += "." + frac
	}
	if neg {
		s = "-" + s
	}
	return s
}

func when(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04 UTC")
}

func relative(at, t int64) string {
	if at >= t {
		return "in " + duration(at-t)
	}
	return duration(t-at) + " ago"
}

func duration(s int64) string {
	switch {
	case s >= 86400:
		d, h := s/86400, (s%86400)/3600
		if h == 0 {
			return ufmt.Sprintf("%d days", d)
		}
		return ufmt.Sprintf("%dd %dh", d, h)
	case s >= 3600:
		return ufmt.Sprintf("%dh %dm", s/3600, (s%3600)/60)
	case s >= 60:
		return ufmt.Sprintf("%d min", s/60)
	}
	return ufmt.Sprintf("%d s", s)
}

// Gnome Tavern — an on-chain tavern on Gno.land.
//
// Patrons claim free Tavern Ale (ALE, a GRC20 token) from a rate-limited
// faucet, buy drinks from the menu with ALE, and every tab lives on-chain.
// The realm's Render() page is the tavern itself: menu, top patrons, and
// per-address balance / tab lookups.
//
// Deployed on the Onyx testnet (chain-id onyx-1) at:
//   gno.land/r/g1x7gechxs30vum6u5mwsg4xkv2m7g2kkas7vzj6/tavern
package tavern

import (
	"strings"
	"time"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	decimals       = 6
	oneALE         = 1_000_000 // 1 ALE = 1_000_000 base units
	faucetAmount   = 100 * oneALE
	faucetCap      = 100_000 * oneALE
	faucetCooldown = 24 * time.Hour
	initialSupply  = 1_000_000 * oneALE
)

var (
	Token         *grc20.Token
	privateLedger *grc20.PrivateLedger
	userTeller    grc20.Teller
	// Ownable is the tavern keeper: the deployer. It owns the till and
	// the mint/burn admin functions.
	Ownable = ownable.NewWithAddress("g1x7gechxs30vum6u5mwsg4xkv2m7g2kkas7vzj6")
)

// drink is one item on the tavern menu. price is in ALE base units.
type drink struct {
	name  string
	price int64
}

var menu = []drink{
	{"Gnome Stout", 50 * oneALE},
	{"Fairy Fizz", 30 * oneALE},
	{"Dragon's Breath Ale", 120 * oneALE},
	{"Mushroom Mead", 80 * oneALE},
	{"Tavern Water", 5 * oneALE},
}

var (
	// lastClaim records the last faucet claim per address (block time).
	lastClaim map[address]time.Time
	// faucetMinted tracks total ALE minted by the faucet (capped).
	faucetMinted int64
	// tabDrinks counts drinks per patron, keyed "address|drink name".
	tabDrinks map[string]int
	// tabSpent totals ALE spent per patron (base units).
	tabSpent map[address]int64
	// patrons lists every address that ever bought a drink, in order.
	patrons  []address
	isPatron map[address]bool
)

func init(cur realm) {
	Token, privateLedger = grc20.NewToken("Tavern Ale", "ALE", decimals, 0, cur)
	userTeller = privateLedger.CallerTeller()
	privateLedger.Mint(Ownable.Owner(), initialSupply)
	grc20reg.Register(cross(cur), Token, "")
	lastClaim = make(map[address]time.Time)
	tabDrinks = make(map[string]int)
	tabSpent = make(map[address]int64)
	isPatron = make(map[address]bool)
}

// formatALE renders base units as "123.456789 ALE".
// (Gno's ufmt does not zero-pad %06d, so the fraction is padded by hand.)
func formatALE(amount int64) string {
	frac := ufmt.Sprintf("%d", amount%oneALE)
	for len(frac) < 6 {
		frac = "0" + frac
	}
	return ufmt.Sprintf("%d.%s ALE", amount/oneALE, frac)
}

// menuPrice looks a drink up by exact name.
func menuPrice(name string) (int64, bool) {
	for _, d := range menu {
		if d.name == name {
			return d.price, true
		}
	}
	return 0, false
}

// Faucet gives the caller 100 ALE, at most once every 24 hours per address,
// until 100,000 ALE have been handed out in total. Returns the amount minted.
func Faucet(cur realm) int64 {
	caller := cur.Previous().Address()
	now := time.Now()
	if last, ok := lastClaim[caller]; ok {
		if now.Sub(last) < faucetCooldown {
			panic("faucet cooldown: one claim per address every 24h")
		}
	}
	if faucetMinted+faucetAmount > faucetCap {
		panic("faucet empty: cap reached")
	}
	lastClaim[caller] = now
	faucetMinted += faucetAmount
	checkErr(privateLedger.Mint(caller, faucetAmount))
	return faucetAmount
}

// BuyDrink pays for a drink from the menu with the caller's ALE and adds it
// to their tab. The ALE goes to the tavern till (the owner). Returns a
// confirmation with the new tab total.
func BuyDrink(cur realm, name string) string {
	caller := cur.Previous().Address()
	price, ok := menuPrice(name)
	if !ok {
		panic("unknown drink: " + name)
	}
	checkErr(userTeller.Transfer(0, cur, Ownable.Owner(), price))
	tabDrinks[caller.String()+"|"+name]++
	tabSpent[caller] += price
	if !isPatron[caller] {
		isPatron[caller] = true
		patrons = append(patrons, caller)
	}
	return ufmt.Sprintf("Enjoy your %s! Tab total: %s.", name, formatALE(tabSpent[caller]))
}

// Menu returns the drink menu as plain text.
func Menu() string {
	s := ""
	for _, d := range menu {
		s += ufmt.Sprintf("- %s: %s\n", d.name, formatALE(d.price))
	}
	return s
}

// TabOf returns a human-readable tab for an address.
func TabOf(addr address) string {
	if !isPatron[addr] {
		return "No tab yet. Buy a drink first!"
	}
	s := ufmt.Sprintf("Tab total: %s\n", formatALE(tabSpent[addr]))
	for _, d := range menu {
		if n := tabDrinks[addr.String()+"|"+d.name]; n > 0 {
			s += ufmt.Sprintf("- %s x%d\n", d.name, n)
		}
	}
	return s
}

// TopPatrons returns the top 5 patrons by ALE spent, as plain text.
func TopPatrons() string {
	if len(patrons) == 0 {
		return "No patrons yet. Be the first to buy a round!\n"
	}
	picked := make(map[address]bool)
	s := ""
	for n := 0; n < 5 && n < len(patrons); n++ {
		var best address
		var bestSpent int64 = -1
		for _, p := range patrons {
			if picked[p] {
				continue
			}
			if tabSpent[p] > bestSpent {
				bestSpent = tabSpent[p]
				best = p
			}
		}
		if bestSpent < 0 {
			break
		}
		picked[best] = true
		s += ufmt.Sprintf("%d. %s — %s\n", n+1, best.String(), formatALE(bestSpent))
	}
	return s
}

// FaucetInfo reports how much ALE the faucet has left to hand out.
func FaucetInfo() string {
	return ufmt.Sprintf("Faucet: %s claimed of %s cap, %s per claim, one claim per address every 24h.",
		formatALE(faucetMinted), formatALE(faucetCap), formatALE(faucetAmount))
}

// TotalSupply returns the total ALE in existence.
func TotalSupply() int64 {
	return userTeller.TotalSupply()
}

// BalanceOf returns the ALE balance of an address (base units).
func BalanceOf(owner address) int64 {
	return userTeller.BalanceOf(owner)
}

// Allowance returns how much spender may spend on behalf of owner.
func Allowance(owner, spender address) int64 {
	return userTeller.Allowance(owner, spender)
}

// Transfer moves the caller's ALE to another address.
func Transfer(cur realm, to address, amount int64) {
	checkErr(userTeller.Transfer(0, cur, to, amount))
}

// Approve lets spender spend up to amount of the caller's ALE.
func Approve(cur realm, spender address, amount int64) {
	checkErr(userTeller.Approve(0, cur, spender, amount))
}

// TransferFrom moves ALE from one address to another using an allowance.
func TransferFrom(cur realm, from, to address, amount int64) {
	checkErr(userTeller.TransferFrom(0, cur, from, to, amount))
}

// Mint creates new ALE. Tavern keeper only.
func Mint(cur realm, to address, amount int64) {
	Ownable.AssertOwnedBy(cur.Previous().Address())
	checkErr(privateLedger.Mint(to, amount))
}

// Burn destroys ALE from an address. Tavern keeper only.
func Burn(cur realm, from address, amount int64) {
	Ownable.AssertOwnedBy(cur.Previous().Address())
	checkErr(privateLedger.Burn(from, amount))
}

// Render is the tavern's web page, served by gnoweb as Markdown.
// NOTE: path segments are attacker-controlled input; anything echoed back
// is passed through sanitize.InlineText first.
func Render(path string) string {
	parts := strings.Split(path, "/")
	switch {
	case path == "":
		s := "# 🍺 Gnome Tavern\n\n"
		s += "An on-chain tavern on Gno.land. Claim free **Tavern Ale (ALE)**, buy drinks from the menu, and your tab lives on-chain forever.\n\n"
		s += Token.RenderHome()
		s += "\n## Menu\n\n" + Menu()
		s += "\n## How to drink\n\n"
		s += "1. `Faucet()` — claim 100 ALE (once every 24h per address).\n"
		s += "2. `BuyDrink(\"Gnome Stout\")` — pay ALE, get it on your tab.\n"
		s += "3. `TabOf(<your address>)` — see your tab.\n\n"
		s += "## Top patrons\n\n" + TopPatrons()
		s += "\n## Faucet\n\n" + FaucetInfo() + "\n"
		return s
	case len(parts) == 2 && parts[0] == "balance":
		owner := address(parts[1])
		return ufmt.Sprintf("Balance of %s: %s\n", sanitize.InlineText(parts[1]), formatALE(BalanceOf(owner)))
	case len(parts) == 2 && parts[0] == "tab":
		addr := address(parts[1])
		return "Tab of " + sanitize.InlineText(parts[1]) + ":\n\n" + TabOf(addr)
	default:
		return "404\n"
	}
}

func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

package tavern

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// cur is a zero-value realm used as a placeholder when forwarding to
// uassert helpers that take an `rlm realm` param. The test callbacks do
// their crossing inside the callback, so rlm is ignored here.
var cur realm

func TestTokenBasics(cur realm, t *testing.T) {
	admin := address("g1x7gechxs30vum6u5mwsg4xkv2m7g2kkas7vzj6")
	alice := testutils.TestAddress("alice")

	uassert.Equal(t, TotalSupply(), int64(1_000_000*oneALE))
	uassert.Equal(t, BalanceOf(admin), int64(1_000_000*oneALE))
	uassert.Equal(t, BalanceOf(alice), int64(0))
	uassert.Equal(t, Token.GetName(), "Tavern Ale")
	uassert.Equal(t, Token.GetSymbol(), "ALE")
	uassert.Equal(t, Token.GetDecimals(), 6)
}

func TestMenuAndRender(cur realm, t *testing.T) {
	menu := Menu()
	uassert.Equal(t, menu, "- Gnome Stout: 50.000000 ALE\n- Fairy Fizz: 30.000000 ALE\n- Dragon's Breath Ale: 120.000000 ALE\n- Mushroom Mead: 80.000000 ALE\n- Tavern Water: 5.000000 ALE\n")

	home := Render("")
	if !contains(home, "Gnome Tavern") {
		t.Fatalf("home page should mention Gnome Tavern")
	}
	if !contains(home, "Gnome Stout") {
		t.Fatalf("home page should list the menu")
	}
	if !contains(home, "Top patrons") {
		t.Fatalf("home page should list top patrons")
	}
	uassert.Equal(t, Render("nonsense/path/here"), "404\n")
}

func TestFaucet(cur realm, t *testing.T) {
	bob := testutils.TestAddress("bob")

	testing.SetOriginCaller(bob)
	got := Faucet(cross(cur))
	uassert.Equal(t, got, int64(faucetAmount))
	uassert.Equal(t, BalanceOf(bob), int64(100*oneALE))
	uassert.Equal(t, TotalSupply(), int64(1_000_000*oneALE+100*oneALE))
	uassert.Equal(t, FaucetInfo(), "Faucet: 100.000000 ALE claimed of 100000.000000 ALE cap, 100.000000 ALE per claim, one claim per address every 24h.")

	// A second claim in the same block must fail: the 24h cooldown.
	uassert.AbortsContains(t, cur, "faucet cooldown", func() {
		Faucet(cross(cur))
	})
	// ...and the failed claim changed nothing.
	uassert.Equal(t, BalanceOf(bob), int64(100*oneALE))

	// Another address can still claim.
	alice := testutils.TestAddress("alice")
	testing.SetOriginCaller(alice)
	Faucet(cross(cur))
	uassert.Equal(t, BalanceOf(alice), int64(100*oneALE))
}

func TestBuyDrink(cur realm, t *testing.T) {
	admin := address("g1x7gechxs30vum6u5mwsg4xkv2m7g2kkas7vzj6")
	// NOTE: test functions in one file share realm state, so each test
	// uses its own caller address (bob already claimed in TestFaucet).
	carol := testutils.TestAddress("carol")

	testing.SetOriginCaller(carol)
	Faucet(cross(cur))

	msg := BuyDrink(cross(cur), "Gnome Stout")
	uassert.Equal(t, msg, "Enjoy your Gnome Stout! Tab total: 50.000000 ALE.")
	uassert.Equal(t, BalanceOf(carol), int64(50*oneALE))
	// The 50 ALE went to the tavern till (the owner).
	uassert.Equal(t, BalanceOf(admin), int64(1_000_000*oneALE+50*oneALE))

	tab := TabOf(carol)
	if !contains(tab, "Gnome Stout x1") {
		t.Fatalf("tab should list the stout, got: %s", tab)
	}
	if !contains(tab, "50.000000 ALE") {
		t.Fatalf("tab total should be 50 ALE, got: %s", tab)
	}

	// A second round updates the same tab.
	BuyDrink(cross(cur), "Fairy Fizz")
	uassert.Equal(t, BalanceOf(carol), int64(20*oneALE))
	tab = TabOf(carol)
	if !contains(tab, "Gnome Stout x1") || !contains(tab, "Fairy Fizz x1") {
		t.Fatalf("tab should list both drinks, got: %s", tab)
	}
	if !contains(tab, "80.000000 ALE") {
		t.Fatalf("tab total should be 80 ALE, got: %s", tab)
	}

	// The leaderboard names carol.
	top := TopPatrons()
	if !contains(top, carol.String()) {
		t.Fatalf("top patrons should list carol, got: %s", top)
	}

	// An unknown drink aborts and changes nothing.
	uassert.AbortsContains(t, cur, "unknown drink", func() {
		BuyDrink(cross(cur), "Unicorn Tears")
	})
	uassert.Equal(t, BalanceOf(carol), int64(20*oneALE))
}

func TestTransferAndRenderPaths(cur realm, t *testing.T) {
	dave := testutils.TestAddress("dave")
	erin := testutils.TestAddress("erin")

	testing.SetOriginCaller(dave)
	Faucet(cross(cur))
	Transfer(cross(cur), erin, 40*oneALE)
	uassert.Equal(t, BalanceOf(dave), int64(60*oneALE))
	uassert.Equal(t, BalanceOf(erin), int64(40*oneALE))

	// Render sub-pages echo the sanitized address and the live state.
	bal := Render("balance/" + dave.String())
	if !contains(bal, "60.000000 ALE") {
		t.Fatalf("balance page should show 60 ALE, got: %s", bal)
	}
	tab := Render("tab/" + erin.String())
	if !contains(tab, "No tab yet") {
		t.Fatalf("erin has no tab yet, got: %s", tab)
	}
}

func TestMintIsOwnerOnly(cur realm, t *testing.T) {
	frank := testutils.TestAddress("frank")
	testing.SetOriginCaller(frank)
	// Only the tavern keeper (the deployer) may mint.
	uassert.AbortsContains(t, cur, "not owner", func() {
		Mint(cross(cur), frank, 1)
	})
}

func contains(s, sub string) bool {
	if len(sub) == 0 {
		return true
	}
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

// Package tapmath is the pure math behind Tapster price feeds: medians,
// deviations and unit conversions, all in integer arithmetic so every
// node computes exactly the same answer.
//
// It has no state and no imports of realms, so any realm on gno.land can
// import it to do the same conversions Tapster does.
package tapmath

// BPS is the number of basis points in 100%.
const BPS int64 = 10000

// MaxDecimals is the largest price precision tapmath accepts.
const MaxDecimals = 8

// UgnotPerGnot is the number of ugnot in one GNOT.
const UgnotPerGnot int64 = 1000000

const maxInt64 int64 = 9223372036854775807

// Median returns the median of values without modifying the input.
// For an even count it returns the floor of the mean of the two middle
// values. It panics on an empty slice.
func Median(values []int64) int64 {
	n := len(values)
	if n == 0 {
		panic("tapmath: median of empty slice")
	}
	s := make([]int64, n)
	copy(s, values)
	insertionSort(s)
	if n%2 == 1 {
		return s[n/2]
	}
	a, b := s[n/2-1], s[n/2]
	// a/2 + b/2 + carry avoids overflow of a+b.
	return a/2 + b/2 + (a%2+b%2)/2
}

// WeightedMedian returns the weighted median of values: the smallest value
// at which the cumulative weight reaches at least half of the total weight.
// With equal weights it returns the lower middle value. Weights must be
// positive. Moving it requires controlling half of the total weight, so
// when weights are stake, influence costs stake.
func WeightedMedian(values, weights []int64) int64 {
	n := len(values)
	if n == 0 {
		panic("tapmath: weighted median of empty slice")
	}
	if len(weights) != n {
		panic("tapmath: values and weights differ in length")
	}
	v := make([]int64, n)
	w := make([]int64, n)
	copy(v, values)
	copy(w, weights)
	var total int64
	for i := 0; i < n; i++ {
		if w[i] <= 0 {
			panic("tapmath: weights must be positive")
		}
		if total > maxInt64-w[i] {
			panic("tapmath: total weight overflows")
		}
		total += w[i]
	}
	// Sort pairs by value (insertion sort, small n).
	for i := 1; i < n; i++ {
		vi, wi := v[i], w[i]
		j := i - 1
		for j >= 0 && v[j] > vi {
			v[j+1], w[j+1] = v[j], w[j]
			j--
		}
		v[j+1], w[j+1] = vi, wi
	}
	half := total/2 + total%2 // ceil(total/2)
	var cum int64
	for i := 0; i < n; i++ {
		cum += w[i]
		if cum >= half {
			return v[i]
		}
	}
	return v[n-1]
}

// insertionSort sorts in place. Report sets are small (tens of values),
// so this is cheaper in gas than a general sort.
func insertionSort(s []int64) {
	for i := 1; i < len(s); i++ {
		v := s[i]
		j := i - 1
		for j >= 0 && s[j] > v {
			s[j+1] = s[j]
			j--
		}
		s[j+1] = v
	}
}

// DeviationBps returns |value-ref| / ref in basis points, rounded down,
// capped at maxInt64 bps. ref must be positive.
func DeviationBps(value, ref int64) int64 {
	if ref <= 0 {
		panic("tapmath: reference must be positive")
	}
	d := value - ref
	if d < 0 {
		d = -d
	}
	if d > maxInt64/BPS {
		return maxInt64
	}
	return d * BPS / ref
}

// Within reports whether value is within tolBps basis points of ref.
func Within(value, ref, tolBps int64) bool {
	return DeviationBps(value, ref) <= tolBps
}

// ApplyBps returns amount * bps / 10000, rounded down.
func ApplyBps(amount, bps int64) int64 {
	if amount < 0 || bps < 0 {
		panic("tapmath: negative input")
	}
	if bps > BPS {
		panic("tapmath: bps above 100%")
	}
	// amount/BPS*bps + (amount%BPS)*bps/BPS keeps intermediates small.
	return amount/BPS*bps + (amount%BPS)*bps/BPS
}

// Pow10 returns 10^n for 0 <= n <= 18.
func Pow10(n int) int64 {
	if n < 0 || n > 18 {
		panic("tapmath: pow10 out of range")
	}
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

// UsdCentsToUgnot converts a USD amount in cents to ugnot using a
// GNOT/USD price with the given number of decimals. It rounds UP, so a
// payer always covers the full USD amount.
//
// Example: price 60000 with 6 decimals means 1 GNOT = $0.06, so
// 600 cents ($6.00) is 100 GNOT = 100000000 ugnot.
func UsdCentsToUgnot(cents, price int64, decimals int) int64 {
	if cents < 0 {
		panic("tapmath: negative amount")
	}
	if price <= 0 {
		panic("tapmath: price must be positive")
	}
	if decimals < 0 || decimals > MaxDecimals {
		panic("tapmath: unsupported decimals")
	}
	// ugnot = cents * 10^decimals * 10^6 / (100 * price)
	//       = cents * 10^(decimals+4) / price
	scale := Pow10(decimals + 4)
	if cents > maxInt64/scale {
		panic("tapmath: amount too large")
	}
	num := cents * scale
	q := num / price
	if num%price != 0 {
		q++
	}
	return q
}

// UgnotToUsdCents converts ugnot to USD cents at a GNOT/USD price with the
// given decimals, rounding down.
func UgnotToUsdCents(ugnot, price int64, decimals int) int64 {
	if ugnot < 0 {
		panic("tapmath: negative amount")
	}
	if price <= 0 {
		panic("tapmath: price must be positive")
	}
	if decimals < 0 || decimals > MaxDecimals {
		panic("tapmath: unsupported decimals")
	}
	scale := Pow10(decimals + 4)
	// cents = ugnot * price / 10^(decimals+4); split to avoid overflow.
	return ugnot/scale*price + (ugnot%scale)*price/scale
}

// FormatFixed renders an integer with the given decimals as a decimal
// string, e.g. FormatFixed(60123, 6) == "0.060123".
func FormatFixed(v int64, decimals int) string {
	neg := v < 0
	if neg {
		v = -v
	}
	s := itoa(v)
	if decimals > 0 {
		for len(s) <= decimals {
			s = "0" + s
		}
		s = s[:len(s)-decimals] + "." + s[len(s)-decimals:]
	}
	if neg {
		s = "-" + s
	}
	return s
}

// FormatRounded renders v with decimals, keeping at most keep fractional
// digits (truncated). Useful for display, e.g. BTC at 2 decimals.
func FormatRounded(v int64, decimals, keep int) string {
	if keep >= decimals {
		return FormatFixed(v, decimals)
	}
	cut := Pow10(decimals - keep)
	return FormatFixed(v/cut, keep)
}

func itoa(v int64) string {
	if v == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	return string(buf[i:])
}

package tapster

import (
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/nt/ufmt/v0"
)

// The functions in this file are free, read-only and safe to call from any
// realm. They return plain values, never pointers to internal state.

// Latest returns the latest finalized price for pair, its decimals, the
// unix time it was finalized and its round. ok is false if the feed does
// not exist or has no answer yet.
//
//	price, dec, at, _, ok := tapster.Latest("GNOT-USD")
func Latest(pair string) (price int64, decimals int, updatedAt int64, round int64, ok bool) {
	v := feeds.Get(pair)
	if v == nil {
		return 0, 0, 0, 0, false
	}
	f := v.(*Feed)
	if !f.hasAnswer {
		return 0, f.Decimals, 0, 0, false
	}
	return f.latest.Price, f.Decimals, f.latest.At, f.latest.Round, true
}

// PriceFresh returns the latest price for pair only if it is at most
// maxAgeSecs old. Use it whenever money moves on the price.
//
//	price, dec, ok := tapster.PriceFresh("GNOT-USD", 600)
//	if !ok { panic("GNOT-USD price is stale") }
func PriceFresh(pair string, maxAgeSecs int64) (price int64, decimals int, ok bool) {
	p, d, at, _, has := Latest(pair)
	if !has {
		return 0, d, false
	}
	if now()-at > maxAgeSecs {
		return 0, d, false
	}
	return p, d, true
}

// MustPriceFresh is PriceFresh that panics when the price is missing or
// stale, which aborts the caller's transaction.
func MustPriceFresh(pair string, maxAgeSecs int64) (price int64, decimals int) {
	p, d, ok := PriceFresh(pair, maxAgeSecs)
	if !ok {
		panic("tapster: no fresh price for " + pair)
	}
	return p, d
}

// Pairs returns the feed names, comma-separated.
func Pairs() string {
	var out []string
	feeds.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return strings.Join(out, ",")
}

// History returns up to n most recent answers for pair as
// "unix:price" pairs, comma-separated, oldest first.
func History(pair string, n int) string {
	f := mustFeed(pair)
	h := f.history
	if n > 0 && n < len(h) {
		h = h[len(h)-n:]
	}
	parts := make([]string, len(h))
	for i, a := range h {
		parts[i] = ufmt.Sprintf("%d:%d", a.At, a.Price)
	}
	return strings.Join(parts, ",")
}

// ReporterStake returns a reporter's current stake and claimable rewards.
func ReporterStake(addr address) (stake int64, rewards int64, active bool) {
	r := getReporter(addr)
	if r == nil {
		return 0, 0, false
	}
	return r.Stake, r.Rewards, r.ExitAt == 0 && r.Stake >= minStake
}

// Admin returns the admin address.
func Admin() address { return admin }

// MinStake returns the minimum stake in ugnot.
func MinStake() int64 { return minStake }

// Consumer is a realm that declared it uses Tapster prices.
type Consumer struct {
	Path  string
	Note  string
	Since int64
}

var consumers = avl.NewTree() // pkgpath -> *Consumer

// RegisterConsumer lists the calling realm on the "Used by" section. It
// must be called by a realm (not an account), typically from its init:
//
//	func init(cur realm) { tapster.RegisterConsumer(cross(cur), "bar tabs in USD") }
func RegisterConsumer(cur realm, note string) {
	assertCurrent(cur)
	prev := cur.Previous()
	if prev.PkgPath() == "" || !strings.HasPrefix(prev.PkgPath(), "gno.land/r/") {
		panic("only realms can register as consumers")
	}
	if len(note) > 80 {
		panic("note too long (max 80)")
	}
	for _, c := range note {
		if c == '[' || c == ']' || c == '(' || c == ')' || c == '<' || c == '>' || c == '|' || c == '`' || c == '\n' {
			panic("note contains characters that are not allowed")
		}
	}
	path := prev.PkgPath()
	if v := consumers.Get(path); v != nil {
		v.(*Consumer).Note = note
		return
	}
	consumers.Set(path, &Consumer{Path: path, Note: note, Since: now()})
	logEvent("consumer", path+" started using Tapster")
}

// Consumers returns the registered consumer realm paths, comma-separated.
func Consumers() string {
	var out []string
	consumers.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return strings.Join(out, ",")
}

