func feedJSON(f *Feed, withHistory bool) string {
	s := ufmt.Sprintf("{\"pair\":\"%s\",\"decimals\":%d,\"price\":%d,\"updatedAt\":%d,\"round\":%d,\"reports\":%d,\"spreadBps\":%d,\"pool\":%d,\"roundSecs\":%d,\"minReports\":%d,\"paused\":%t,\"hasAnswer\":%t",
		f.Pair, f.Decimals, f.latest.Price, f.latest.At, f.latest.Round, f.latest.Reports, f.latest.Spread, f.Pool, f.RoundSecs, f.MinReports, f.Paused, f.hasAnswer)
	if withHistory {
		h := make([]string, len(f.history))
		for i, a := range f.history {
			h[i] = ufmt.Sprintf("[%d,%d]", a.At, a.Price)
		}
		s += ",\"history\":[" + strings.Join(h, ",") + "]"
		rs := make([]string, len(f.lastReports))
		for i, r := range f.lastReports {
			rs[i] = ufmt.Sprintf("{\"reporter\":\"%s\",\"name\":\"%s\",\"price\":%d,\"weight\":%d,\"devBps\":%d,\"outcome\":\"%s\"}",
				r.Reporter.String(), jsonEscape(displayName(r.Reporter)), r.Price, r.Weight, r.DevBps, r.Outcome)
		}
		s += ",\"lastRound\":[" + strings.Join(rs, ",") + "]"
	}
	return s + "}"
}

func jsonEscape(s string) string {
	// Names are restricted to safe characters by cleanName; escape quotes
	// and backslashes anyway.
	s = strings.ReplaceAll(s, "\\", "\\\\")
	return strings.ReplaceAll(s, "\"", "\\\"")
}

// ----------------------------------------------------------------------
// SVG charts (rendered by the realm itself)

func scalePoints(h []Answer, w, ht, pad int) (string, int64, int64) {
	lo, hi := h[0].Price, h[0].Price
	for _, a := range h {
		if a.Price < lo {
			lo = a.Price
		}
		if a.Price > hi {
			hi = a.Price
		}
	}
	span := hi - lo
	if span == 0 {
		span = 1
	}
	var pts []string
	n := len(h)
	for i, a := range h {
		x := pad
		if n > 1 {
			x = pad + i*(w-2*pad)/(n-1)
		}
		y := ht - pad - int((a.Price-lo)*int64(ht-2*pad)/span)
		pts = append(pts, ufmt.Sprintf("%d,%d", x, y))
	}
	return strings.Join(pts, " "), lo, hi
}

func svgImage(alt, svg string) string {
	return "![" + alt + "](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg)) + ")"
}

func sparkline(f *Feed) string {
	h := f.history
	if len(h) > 40 {
		h = h[len(h)-40:]
	}
	if len(h) < 2 {
		return "—"
	}
	pts, _, _ := scalePoints(h, 120, 28, 3)
	color := "#16a34a"
	if h[len(h)-1].Price < h[0].Price {
		color = "#dc2626"
	}
	svg := `<svg xmlns="http://www.w3.org/2000/svg" width="120" height="28" viewBox="0 0 120 28"><polyline points="` + pts + `" fill="none" stroke="` + color + `" stroke-width="2" stroke-linejoin="round"/></svg>`
	return svgImage(f.Pair+" trend", svg)
}

func chart(f *Feed, w, ht int) string {
	h := f.history
	if len(h) < 2 {
		return "_The chart appears after two answers._"
	}
	pad := 24
	pts, lo, hi := scalePoints(h, w, ht, pad)
	color := "#16a34a"
	if h[len(h)-1].Price < h[0].Price {
		color = "#dc2626"
	}
	area := ufmt.Sprintf("%d,%d %s %d,%d", pad, ht-pad, pts, w-pad, ht-pad)
	var s strings.Builder
	s.WriteString(ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d" font-family="sans-serif" font-size="11">`, w, ht, w, ht))
	s.WriteString(ufmt.Sprintf(`<rect width="%d" height="%d" fill="#fffbeb" rx="8"/>`, w, ht))
	s.WriteString(`<polygon points="` + area + `" fill="` + color + `" opacity="0.12"/>`)
	s.WriteString(`<polyline points="` + pts + `" fill="none" stroke="` + color + `" stroke-width="2.5" stroke-linejoin="round"/>`)
	s.WriteString(ufmt.Sprintf(`<text x="%d" y="16" fill="#78350f">high %s</text>`, pad, displayPrice(f, hi)))
	s.WriteString(ufmt.Sprintf(`<text x="%d" y="%d" fill="#78350f">low %s</text>`, pad, ht-6, displayPrice(f, lo)))
	s.WriteString(ufmt.Sprintf(`<text x="%d" y="16" fill="#78350f" text-anchor="end">last %d rounds</text>`, w-pad, len(h)))
	s.WriteString(`</svg>`)
	return svgImage(f.Pair+" price chart", s.String())
}

func renderJSONReporters() string {
	var items []string
	reporters.Iterate("", "", func(_ string, v any) bool {
		r := v.(*Reporter)
		items = append(items, ufmt.Sprintf("{\"address\":\"%s\",\"name\":\"%s\",\"stake\":%d,\"rewards\":%d,\"earned\":%d,\"reports\":%d,\"accurate\":%d,\"outliers\":%d,\"slashed\":%d,\"exitAt\":%d,\"active\":%t}",
			r.Addr.String(), jsonEscape(r.Name), r.Stake, r.Rewards, r.Earned, r.Reports, r.Accurate, r.Outliers, r.Slashed, r.ExitAt, r.ExitAt == 0 && r.Stake >= minStake))
		return false
	})
	var ev []string
	for i := len(events) - 1; i >= 0 && i >= len(events)-30; i-- {
		e := events[i]
		ev = append(ev, ufmt.Sprintf("{\"at\":%d,\"kind\":\"%s\",\"text\":\"%s\"}", e.At, e.Kind, jsonEscape(e.Text)))
	}
	return ufmt.Sprintf("{\"minStake\":%d,\"totalSlashed\":%d,\"totalRewards\":%d,\"consumers\":\"%s\",\"reporters\":[%s],\"events\":[%s]}",
		minStake, totalSlashed, totalRewards, Consumers(), strings.Join(items, ","), strings.Join(ev, ","))
}

package tapster

import (
	"chain"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/g1wdkzlexhwjvltvzkfmexyrm6jf5syzrrg0ymzy/tapmath/v0"
)

// Report outcomes.
const (
	OutcomeAccurate = "accurate"
	OutcomeNeutral  = "neutral"
	OutcomeOutlier  = "outlier"
	OutcomeNoQuorum = "no quorum"
)

// ----------------------------------------------------------------------
// Reporter lifecycle

// Stake adds the ugnot sent with the call to the caller's reporter stake,
// registering the caller as a reporter on first use. name is optional and
// shown on the leaderboard ("" keeps the current name).
func Stake(cur realm, name string) {
	assertCurrent(cur)
	amount := receivedUgnot(cur)
	if amount <= 0 {
		panic("send ugnot to stake, e.g. -send 1000000ugnot")
	}
	caller := cur.Previous().Address()
	// Validate everything before writing any state.
	if name != "" {
		name = cleanName(name)
	}
	r := getReporter(caller)
	var have int64
	if r != nil {
		if r.ExitAt != 0 {
			panic("this reporter is exiting; withdraw first, then stake again")
		}
		have = r.Stake
	}
	if have+amount < minStake {
		panic(ufmt.Sprintf("total stake must be at least %d ugnot", minStake))
	}
	if r == nil {
		r = &Reporter{Addr: caller, JoinedAt: now()}
		reporters.Set(caller.String(), r)
		logEvent("join", displayNameOr(caller, name)+" joined as a reporter")
	}
	if name != "" {
		r.Name = name
	}
	r.Stake += amount
	chain.Emit("Stake", "reporter", caller.String(), "amount", itoa(amount), "stake", itoa(r.Stake))
}

func displayNameOr(a address, name string) string {
	if name != "" {
		return cleanName(name)
	}
	return shortAddr(a)
}

// SetName changes the caller's display name.
func SetName(cur realm, name string) {
	assertCurrent(cur)
	r := getReporter(cur.Previous().Address())
	if r == nil {
		panic("not a reporter")
	}
	r.Name = cleanName(name)
}

// RequestExit stops the caller from reporting and starts the unbonding
// period. Stake stays slashable until it ends, so a reporter cannot submit
// a bad price and leave before the round closes.
func RequestExit(cur realm) {
	assertCurrent(cur)
	caller := cur.Previous().Address()
	r := getReporter(caller)
	if r == nil {
		panic("not a reporter")
	}
	if r.ExitAt != 0 {
		panic("exit already requested")
	}
	r.ExitAt = now() + unbondingSecs
	logEvent("exit", displayName(caller)+" requested exit")
	chain.Emit("RequestExit", "reporter", caller.String(), "withdrawableAt", itoa(r.ExitAt))
}

// Withdraw pays out stake and rewards after the unbonding period and
// removes the reporter.
func Withdraw(cur realm) {
	assertCurrent(cur)
	caller := cur.Previous().Address()
	r := getReporter(caller)
	if r == nil {
		panic("not a reporter")
	}
	if r.ExitAt == 0 {
		panic("call RequestExit first")
	}
	if now() < r.ExitAt {
		panic(ufmt.Sprintf("unbonding: withdrawable in %d seconds", r.ExitAt-now()))
	}
	settlePending(caller)
	amount := r.Stake + r.Rewards // read after settling: may have been slashed
	reporters.Remove(caller.String())
	logEvent("withdraw", displayNameOr(caller, r.Name)+" withdrew "+gnot(amount))
	send(cur, caller, amount)
	chain.Emit("Withdraw", "reporter", caller.String(), "amount", itoa(amount))
}

// settlePending finalizes every ended round that holds a report from addr,
// and refuses to continue while one of addr's reports sits in an open
// round. This closes the gap where a reporter could withdraw before a bad
// report was judged.
func settlePending(addr address) {
	t := now()
	feeds.Iterate("", "", func(_ string, v any) bool {
		f := v.(*Feed)
		if f.current == nil {
			return false
		}
		has := false
		for _, rep := range f.current.Reports {
			if rep.Reporter == addr {
				has = true
				break
			}
		}
		if !has {
			return false
		}
		if f.current.ID >= t/f.RoundSecs {
			panic("you have a report in an open round of " + f.Pair + "; try again after it closes")
		}
		finalize(f)
		return false
	})
}

// ClaimRewards pays out the caller's accumulated rewards.
func ClaimRewards(cur realm) {
	assertCurrent(cur)
	caller := cur.Previous().Address()
	r := getReporter(caller)
	if r == nil {
		panic("not a reporter")
	}
	amount := r.Rewards
	if amount == 0 {
		panic("no rewards to claim")
	}
	r.Rewards = 0
	send(cur, caller, amount)
	chain.Emit("ClaimRewards", "reporter", caller.String(), "amount", itoa(amount))
}

// Fund adds the ugnot sent with the call to a feed's reward pool. Anyone
// can sponsor a feed they rely on.
func Fund(cur realm, pair string) {
	assertCurrent(cur)
	amount := receivedUgnot(cur)
	if amount <= 0 {
		panic("send ugnot to fund the pool")
	}
	f := mustFeed(pair)
	f.Pool += amount
	logEvent("fund", displayName(cur.Previous().Address())+" funded "+pair+" with "+gnot(amount))
	chain.Emit("Fund", "pair", pair, "amount", itoa(amount))
}

// ----------------------------------------------------------------------
// Reporting

// Submit records the caller's price for pair in the current round. price
// is an integer with the feed's decimals (6 for the default feeds), so
// $0.061234 is 61234. If the previous round has ended, it is finalized
// first.
func Submit(cur realm, pair string, price int64) {
	assertCurrent(cur)
	caller := cur.Previous().Address()
	r := getReporter(caller)
	if r == nil {
		panic("not a reporter: call Stake first")
	}
	if r.ExitAt != 0 {
		panic("reporter is exiting")
	}
	if r.Stake < minStake {
		panic(ufmt.Sprintf("stake below minimum %d ugnot: top up with Stake", minStake))
	}
	if price <= 0 {
		panic("price must be positive")
	}
	f := mustFeed(pair)
	if f.Paused {
		panic("feed is paused")
	}
	t := now()
	rid := t / f.RoundSecs
	if f.current != nil && f.current.ID < rid {
		finalize(f)
	}
	if f.current == nil {
		f.current = &Round{ID: rid}
	}
	for _, rep := range f.current.Reports {
		if rep.Reporter == caller {
			panic("already reported this round")
		}
	}
	if len(f.current.Reports) >= maxReportsRound {
		panic("round is full")
	}
	f.current.Reports = append(f.current.Reports, Report{
		Reporter: caller,
		Price:    price,
		Weight:   r.Stake,
		At:       t,
	})
	r.Reports++
	chain.Emit("Submit", "pair", pair, "reporter", caller.String(), "price", itoa(price), "round", itoa(rid))
}

// Finalize closes the feed's current round if its time is up. Anyone can
// call it; reporters do it implicitly with the first submit of a new round.
// It returns true if a round was closed.
func Finalize(cur realm, pair string) bool {
	assertCurrent(cur)
	f := mustFeed(pair)
	if f.current == nil {
		return false
	}
	if f.current.ID >= now()/f.RoundSecs {
		return false // round still open
	}
	finalize(f)
	return true
}

func finalize(f *Feed) {
	rd := f.current
	f.current = nil
	if rd == nil || len(rd.Reports) == 0 {
		return
	}
	if len(rd.Reports) < f.MinReports {
		f.roundsMissed++
		for i := range rd.Reports {
			rd.Reports[i].Outcome = OutcomeNoQuorum
		}
		f.lastReports = rd.Reports
		chain.Emit("NoQuorum", "pair", f.Pair, "round", itoa(rd.ID), "reports", itoa(int64(len(rd.Reports))))
		return
	}

	prices := make([]int64, len(rd.Reports))
	weights := make([]int64, len(rd.Reports))
	lo, hi := rd.Reports[0].Price, rd.Reports[0].Price
	for i, rep := range rd.Reports {
		prices[i] = rep.Price
		weights[i] = rep.Weight
		if rep.Price < lo {
			lo = rep.Price
		}
		if rep.Price > hi {
			hi = rep.Price
		}
	}
	answer := tapmath.WeightedMedian(prices, weights)

	for i := range rd.Reports {
		rep := &rd.Reports[i]
		dev := tapmath.DeviationBps(rep.Price, answer)
		rep.DevBps = dev
		rr := getReporter(rep.Reporter)
		switch {
		case dev <= f.ToleranceBps:
			rep.Outcome = OutcomeAccurate
			if rr != nil {
				rr.Accurate++
				reward := f.RewardPerReport
				if reward > f.Pool {
					reward = f.Pool
				}
				f.Pool -= reward
				rr.Rewards += reward
				rr.Earned += reward
				totalRewards += reward
			}
		case dev > f.OutlierBps:
			rep.Outcome = OutcomeOutlier
			if rr != nil {
				rr.Outliers++
				slash := tapmath.ApplyBps(rr.Stake, f.SlashBps)
				rr.Stake -= slash
				rr.Slashed += slash
				f.Pool += slash
				totalSlashed += slash
				logEvent("slash", ufmt.Sprintf("%s slashed %s on %s: reported %s vs answer %s (%s off)",
					displayName(rep.Reporter), gnot(slash), f.Pair,
					tapmath.FormatFixed(rep.Price, f.Decimals), tapmath.FormatFixed(answer, f.Decimals), bpsPct(dev)))
				chain.Emit("Slash", "pair", f.Pair, "reporter", rep.Reporter.String(), "amount", itoa(slash), "devBps", itoa(dev))
			}
		default:
			rep.Outcome = OutcomeNeutral
		}
	}

	var spread int64
	if lo > 0 {
		spread = tapmath.DeviationBps(hi, lo)
	}
	a := Answer{Round: rd.ID, Price: answer, At: now(), Reports: len(rd.Reports), Spread: spread}
	f.latest = a
	f.hasAnswer = true
	f.history = append(f.history, a)
	if len(f.history) > maxHistory {
		f.history = f.history[len(f.history)-maxHistory:]
	}
	f.lastReports = rd.Reports
	chain.Emit("Answer", "pair", f.Pair, "price", itoa(answer), "round", itoa(rd.ID), "reports", itoa(int64(len(rd.Reports))))
}

// ----------------------------------------------------------------------
// Admin (bounded)

// AddFeed creates a new price feed.
func AddFeed(cur realm, pair, description string, decimals int, roundSecs int64, minReports int) {
	assertAdmin(cur)
	addFeed(pair, description, decimals, roundSecs, minReports)
	logEvent("feed", "new feed "+pair)
}

// SetFeedParams tunes a feed. Slashing is capped at 20% per outlier and
// tolerance must be below the outlier threshold.
func SetFeedParams(cur realm, pair string, roundSecs int64, minReports int, toleranceBps, outlierBps, slashBps, rewardPerReport int64) {
	assertAdmin(cur)
	f := mustFeed(pair)
	checkRoundSecs(roundSecs)
	if minReports < 1 || minReports > maxReportsRound {
		panic("minReports out of range")
	}
	if toleranceBps < 0 || outlierBps <= toleranceBps || outlierBps > tapmath.BPS {
		panic("need 0 <= toleranceBps < outlierBps <= 10000")
	}
	if slashBps < 0 || slashBps > maxSlashBps {
		panic("slashBps must be between 0 and 2000")
	}
	if rewardPerReport < 0 {
		panic("rewardPerReport must not be negative")
	}
	if f.current != nil && roundSecs != f.RoundSecs {
		finalize(f) // close the open round under the old schedule
	}
	f.RoundSecs = roundSecs
	f.MinReports = minReports
	f.ToleranceBps = toleranceBps
	f.OutlierBps = outlierBps
	f.SlashBps = slashBps
	f.RewardPerReport = rewardPerReport
	logEvent("params", "updated parameters of "+pair)
}

// SetPaused pauses or resumes a feed.
func SetPaused(cur realm, pair string, paused bool) {
	assertAdmin(cur)
	mustFeed(pair).Paused = paused
}

// SetProtocol sets the minimum stake and unbonding period.
func SetProtocol(cur realm, newMinStake, newUnbondingSecs int64) {
	assertAdmin(cur)
	if newMinStake < 1 {
		panic("minimum stake must be positive")
	}
	if newUnbondingSecs < 60 || newUnbondingSecs > 30*86400 {
		panic("unbonding must be between 60 seconds and 30 days")
	}
	minStake = newMinStake
	unbondingSecs = newUnbondingSecs
}

// TransferAdmin hands the admin role to another address.
func TransferAdmin(cur realm, newAdmin address) {
	assertAdmin(cur)
	if !newAdmin.IsValid() {
		panic("invalid address")
	}
	admin = newAdmin
}

// ----------------------------------------------------------------------
// helpers

func itoa(v int64) string { return tapmath.FormatFixed(v, 0) }

func gnot(u int64) string { return tapmath.FormatRounded(u, 6, 3) + " GNOT" }

func bpsPct(bps int64) string { return tapmath.FormatFixed(bps, 2) + "%" }

// Package tapster is a staked price oracle for gno.land.
//
// Reporters stake GNOT and submit prices for feeds such as GNOT-USD. Each
// feed runs in fixed time rounds. When a round closes, the realm takes the
// median of the reports as the answer, pays reporters who were within the
// feed's tolerance from the feed's reward pool, and slashes part of the
// stake of reporters who were far from the median. Slashed stake goes to
// the reward pool, so honest reporters are paid by dishonest ones.
//
// Any realm can read prices for free with Latest or PriceFresh.
package tapster

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/g1wdkzlexhwjvltvzkfmexyrm6jf5syzrrg0ymzy/tapmath/v0"
)

// Protocol limits. These protect reporters and readers from extreme
// parameters, including from the admin.
const (
	maxHistory      = 120  // answers kept per feed for charts
	maxReportsRound = 64   // reports accepted per round
	maxSlashBps     = 2000 // admin can never slash more than 20% per round
	minRoundSecs    = 15
	maxRoundSecs    = 86400
	maxPairLen      = 16
	maxNameLen      = 32
	maxEvents       = 200
	ugnot           = "ugnot"
)

// Tunable protocol settings (admin-only, bounded).
var (
	minStake      int64 = 1000000 // 1 GNOT to become an active reporter
	unbondingSecs int64 = 3600    // stake stays slashable this long after exit
)

// admin is the realm administrator. The deploy script writes the deployer
// address here. The admin can add feeds and tune parameters within the
// hard limits above, and can never move reporters' stake.
var admin address = "g1wdkzlexhwjvltvzkfmexyrm6jf5syzrrg0ymzy"

// Report is one reporter's price in a round.
type Report struct {
	Reporter address
	Price    int64
	Weight   int64 // reporter's stake when the report was made
	At       int64
	DevBps   int64 // filled at finalization: distance from the answer
	Outcome  string
}

// Round holds the reports collected during one round of a feed.
type Round struct {
	ID      int64
	Reports []Report
}

// Answer is a finalized price.
type Answer struct {
	Round   int64
	Price   int64
	At      int64 // unix seconds when the round was finalized
	Reports int
	Spread  int64 // bps between the lowest and highest report
}

// Feed is one price pair.
type Feed struct {
	Pair            string
	Description     string
	Decimals        int
	RoundSecs       int64
	MinReports      int
	ToleranceBps    int64 // within this: accurate, earns a reward
	OutlierBps      int64 // beyond this: outlier, gets slashed
	SlashBps        int64 // share of stake slashed per outlier report
	RewardPerReport int64 // ugnot paid per accurate report
	Pool            int64 // ugnot available for rewards
	Paused          bool

	current      *Round
	latest       Answer
	hasAnswer    bool
	history      []Answer
	lastReports  []Report // reports of the last finalized round
	roundsMissed int      // rounds closed without quorum
}

// Reporter is a staked price reporter.
type Reporter struct {
	Addr     address
	Name     string
	Stake    int64
	Rewards  int64 // claimable ugnot
	Accurate int
	Outliers int
	Reports  int
	Slashed  int64
	Earned   int64 // lifetime rewards
	JoinedAt int64
	ExitAt   int64 // 0 = active; otherwise unix time stake can be withdrawn
}

// Event is a human-readable log line for the activity page.
type Event struct {
	At   int64
	Kind string
	Text string
}

var (
	feeds     = avl.NewTree() // pair -> *Feed
	reporters = avl.NewTree() // address -> *Reporter
	events    []Event
	totalSlashed int64
	totalRewards int64
)

func init() {
	addFeed("GNOT-USD", "Gno.land GNOT priced in US dollars", 6, 300, 2)
	addFeed("BTC-USD", "Bitcoin priced in US dollars", 6, 300, 2)
	addFeed("ETH-USD", "Ether priced in US dollars", 6, 300, 2)
	addFeed("XAU-USD", "Gold (1 troy ounce) priced in US dollars", 6, 300, 2)
}

func addFeed(pair, desc string, decimals int, roundSecs int64, minReports int) {
	validatePair(pair)
	if feeds.Has(pair) {
		panic("feed already exists: " + pair)
	}
	if decimals < 0 || decimals > tapmath.MaxDecimals {
		panic("decimals must be between 0 and 8")
	}
	checkRoundSecs(roundSecs)
	if minReports < 1 || minReports > maxReportsRound {
		panic("minReports out of range")
	}
	feeds.Set(pair, &Feed{
		Pair:            pair,
		Description:     desc,
		Decimals:        decimals,
		RoundSecs:       roundSecs,
		MinReports:      minReports,
		ToleranceBps:    100,  // 1%
		OutlierBps:      500,  // 5%
		SlashBps:        500,  // 5% of stake
		RewardPerReport: 2000, // 0.002 GNOT
	})
}

func validatePair(pair string) {
	if len(pair) < 3 || len(pair) > maxPairLen {
		panic("pair must be 3-16 characters, like GNOT-USD")
	}
	for _, c := range pair {
		ok := (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-'
		if !ok {
			panic("pair may only use A-Z, 0-9 and '-'")
		}
	}
}

func checkRoundSecs(s int64) {
	if s < minRoundSecs || s > maxRoundSecs {
		panic(ufmt.Sprintf("roundSecs must be between %d and %d", minRoundSecs, maxRoundSecs))
	}
}

func now() int64 { return time.Now().Unix() }

func mustFeed(pair string) *Feed {
	v := feeds.Get(pair)
	if v == nil {
		panic("unknown feed: " + pair)
	}
	return v.(*Feed)
}

func getReporter(addr address) *Reporter {
	v := reporters.Get(addr.String())
	if v == nil {
		return nil
	}
	return v.(*Reporter)
}

func logEvent(kind, text string) {
	events = append(events, Event{At: now(), Kind: kind, Text: text})
	if len(events) > maxEvents {
		events = events[len(events)-maxEvents:]
	}
}

func assertCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
}

// receivedUgnot returns the ugnot sent with this call. The IsUserCall
// guard and the OriginSend read are a pair: only for a direct call from
// an account are the -send coins guaranteed to have reached this realm.
func receivedUgnot(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("call this function directly from an account (gnokey maketx call or a wallet)")
	}
	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("only ugnot is accepted")
		}
	}
	return sent.AmountOf(ugnot)
}

func send(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), to, chain.Coins{{ugnot, amount}})
}

func assertAdmin(cur realm) {
	assertCurrent(cur)
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func displayName(a address) string {
	if r := getReporter(a); r != nil && r.Name != "" {
		return r.Name
	}
	return shortAddr(a)
}

func cleanName(name string) string {
	name = strings.TrimSpace(name)
	if len(name) > maxNameLen {
		panic("name too long (max 32)")
	}
	for _, c := range name {
		ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == ' ' || c == '.'
		if !ok {
			panic("name may only use letters, digits, space, '-', '_' and '.'")
		}
	}
	return name
}

// Package tab is a bar tab priced in US dollars and paid in GNOT.
//
// A bartender opens a tab and adds items in dollars. The customer pays in
// GNOT at the live Tapster GNOT-USD price: the realm converts the bill at
// payment time, refuses stale prices, pays the bartender exactly the
// amount due and refunds any extra GNOT sent. It exists to show how any
// realm can use Tapster prices.
package tab

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/g1wdkzlexhwjvltvzkfmexyrm6jf5syzrrg0ymzy/tapmath/v0"
	"gno.land/r/g1wdkzlexhwjvltvzkfmexyrm6jf5syzrrg0ymzy/tapster/v0"
)

const (
	pricePair     = "GNOT-USD"
	maxPriceAge   = 600       // refuse prices older than 10 minutes
	maxItems      = 30        // per tab
	maxItemCents  = 1000000   // $10,000 per item
	maxTitleLen   = 48
	ugnot         = "ugnot"
	quoteBufferBp = 200 // pay links send 2% extra to absorb price moves; the rest is refunded
)

// Item is one line on a tab.
type Item struct {
	Name  string
	Cents int64
}

// Tab is a bill.
type Tab struct {
	ID        int
	Title     string
	Bartender address
	Items     []Item
	Created   int64

	Paid      bool
	Payer     address
	PaidUgnot int64
	PaidPrice int64 // GNOT-USD price used
	PaidAt    int64
}

var (
	tabs   = avl.NewTree() // zero-padded id -> *Tab
	nextID = 1
	paidTotalCents int64
)

func init(cur realm) {
	tapster.RegisterConsumer(cross(cur), "bar tabs priced in USD, paid in GNOT")
}

func key(id int) string { return ufmt.Sprintf("%08d", id) }

func mustTab(id int) *Tab {
	v := tabs.Get(key(id))
	if v == nil {
		panic("unknown tab")
	}
	return v.(*Tab)
}

func now() int64 { return time.Now().Unix() }

func assertCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
}

func cleanText(s string, max int) string {
	s = strings.TrimSpace(s)
	if s == "" {
		panic("text must not be empty")
	}
	if len(s) > max {
		panic(ufmt.Sprintf("text too long (max %d)", max))
	}
	for _, c := range s {
		if c == '|' || c == '[' || c == ']' || c == '(' || c == ')' || c == '<' || c == '>' || c == '`' || c == '\n' {
			panic("text contains characters that are not allowed")
		}
	}
	return s
}

// Open creates a tab owned by the caller and returns its id.
func Open(cur realm, title string) int {
	assertCurrent(cur)
	t := &Tab{
		ID:        nextID,
		Title:     cleanText(title, maxTitleLen),
		Bartender: cur.Previous().Address(),
		Created:   now(),
	}
	tabs.Set(key(t.ID), t)
	nextID++
	chain.Emit("Open", "id", strconv.Itoa(t.ID), "bartender", t.Bartender.String())
	return t.ID
}

// Add puts an item priced in US cents on an open tab. Bartender only.
func Add(cur realm, id int, name string, cents int64) {
	assertCurrent(cur)
	t := mustTab(id)
	if cur.Previous().Address() != t.Bartender {
		panic("only the bartender can add items")
	}
	if t.Paid {
		panic("tab already paid")
	}
	if cents <= 0 || cents > maxItemCents {
		panic("price must be between 1 cent and $10,000")
	}
	if len(t.Items) >= maxItems {
		panic("tab is full")
	}
	t.Items = append(t.Items, Item{Name: cleanText(name, 32), Cents: cents})
}

// Total returns a tab's total in cents.
func Total(id int) int64 {
	var sum int64
	for _, it := range mustTab(id).Items {
		sum += it.Cents
	}
	return sum
}

// Quote returns the ugnot due for a tab at the current Tapster price and
// whether that price is fresh enough to pay with.
func Quote(id int) (due int64, price int64, ok bool) {
	p, dec, fresh := tapster.PriceFresh(pricePair, maxPriceAge)
	if !fresh {
		return 0, 0, false
	}
	return tapmath.UsdCentsToUgnot(Total(id), p, dec), p, true
}

// Pay settles a tab with the GNOT sent with the call. The bill is
// converted at the live Tapster price; the bartender receives exactly the
// amount due and the payer gets the rest back.
func Pay(cur realm, id int) {
	assertCurrent(cur)
	// IsUserCall + OriginSend are a pair: only for a direct call from an
	// account are the -send coins guaranteed to have reached this realm.
	if !cur.Previous().IsUserCall() {
		panic("call Pay directly from an account")
	}
	sent := unsafe.OriginSend().AmountOf(ugnot)

	t := mustTab(id)
	if t.Paid {
		panic("tab already paid")
	}
	total := Total(id)
	if total == 0 {
		panic("tab is empty")
	}
	price, dec := tapster.MustPriceFresh(pricePair, maxPriceAge)
	due := tapmath.UsdCentsToUgnot(total, price, dec)
	if sent < due {
		panic(ufmt.Sprintf("not enough GNOT: due %d ugnot at $%s/GNOT, sent %d",
			due, tapmath.FormatFixed(price, dec), sent))
	}
	payer := cur.Previous().Address()
	t.Paid = true
	t.Payer = payer
	t.PaidUgnot = due
	t.PaidPrice = price
	t.PaidAt = now()
	paidTotalCents += total

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), t.Bartender, chain.Coins{{ugnot, due}})
	if sent > due {
		bk.SendCoins(cur.Address(), payer, chain.Coins{{ugnot, sent - due}})
	}
	chain.Emit("Pay", "id", strconv.Itoa(id), "cents", strconv.FormatInt(total, 10),
		"ugnot", strconv.FormatInt(due, 10), "price", strconv.FormatInt(price, 10))
}

// ----------------------------------------------------------------------
// Render

func usd(cents int64) string { return "$" + tapmath.FormatFixed(cents, 2) }

func gnot(u int64) string { return tapmath.FormatRounded(u, 6, 4) + " GNOT" }

func short(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func realmPath() string {
	l := txlink.Call("Open")
	if i := strings.Index(l, "$"); i >= 0 {
		return l[:i]
	}
	return l
}

// Render shows open and paid tabs; "tab/<id>" shows one tab.
func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if path == "json" {
		return renderJSON()
	}
	if len(parts) == 2 && parts[0] == "tab" {
		id, err := strconv.Atoi(parts[1])
		if err != nil || !tabs.Has(key(id)) {
			return "# Unknown tab\n\n[Back](" + realmPath() + ")"
		}
		return renderTab(mustTab(id))
	}
	return renderHome()
}

func priceLine() string {
	p, dec, at, _, ok := tapster.Latest(pricePair)
	if !ok {
		return "⏳ Waiting for the first Tapster GNOT-USD price."
	}
	fresh := now()-at <= maxPriceAge
	s := "Live price from [Tapster](/" + tapsterPath() + "): **1 GNOT = $" + tapmath.FormatFixed(p, dec) + "**"
	if !fresh {
		s += " ⚠️ stale, payments are paused until it updates"
	}
	return s
}

func tapsterPath() string {
	// Same namespace as this realm.
	p := strings.TrimPrefix(realmPath(), "/")
	return strings.Replace(p, "/tab/v0", "/tapster/v0", 1)
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# 🍻 Tab\n\n")
	b.WriteString("Bar tabs priced in dollars, paid in GNOT at the live price. Built on Tapster price feeds.\n\n")
	b.WriteString(priceLine() + "\n\n")
	b.WriteString("[Open a tab](" + txlink.NewLink("Open").AddArgs("title", "").URL() + ")")
	b.WriteString(ufmt.Sprintf(" · %s settled so far\n\n", usd(paidTotalCents)))
	b.WriteString("| Tab | Bartender | Items | Total | Status |\n|---|---|---|---|---|\n")
	n := 0
	tabs.ReverseIterate("", "", func(_ string, v any) bool {
		t := v.(*Tab)
		status := "open"
		if t.Paid {
			status = "✅ paid " + gnot(t.PaidUgnot)
		}
		b.WriteString(ufmt.Sprintf("| [#%d %s](%s:tab/%d) | `%s` | %d | %s | %s |\n",
			t.ID, t.Title, realmPath(), t.ID, short(t.Bartender), len(t.Items), usd(Total(t.ID)), status))
		n++
		return n >= 50
	})
	if n == 0 {
		b.WriteString("| No tabs yet | | | | |\n")
	}
	return b.String()
}

func renderTab(t *Tab) string {
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# Tab #%d: %s\n\n", t.ID, t.Title))
	b.WriteString(ufmt.Sprintf("Bartender `%s` · [All tabs](%s)\n\n", short(t.Bartender), realmPath()))
	b.WriteString("| Item | Price |\n|---|---|\n")
	for _, it := range t.Items {
		b.WriteString("| " + it.Name + " | " + usd(it.Cents) + " |\n")
	}
	total := Total(t.ID)
	b.WriteString("| **Total** | **" + usd(total) + "** |\n\n")

	if t.Paid {
		b.WriteString(ufmt.Sprintf("✅ Paid %s by `%s` at $%s/GNOT.\n",
			gnot(t.PaidUgnot), short(t.Payer), tapmath.FormatFixed(t.PaidPrice, 6)))
		return b.String()
	}
	b.WriteString(priceLine() + "\n\n")
	if total == 0 {
		b.WriteString("Empty tab. The bartender adds items with [Add](" + txlink.NewLink("Add").AddArgs("id", strconv.Itoa(t.ID)).URL() + ").\n")
		return b.String()
	}
	due, _, ok := Quote(t.ID)
	if !ok {
		b.WriteString("Payment is paused until Tapster has a fresh GNOT-USD price.\n")
		return b.String()
	}
	send := due + tapmath.ApplyBps(due, quoteBufferBp)
	b.WriteString(ufmt.Sprintf("**Due now: %s**\n\n", gnot(due)))
	b.WriteString("[Pay this tab](" + txlink.NewLink("Pay").AddArgs("id", strconv.Itoa(t.ID)).SetSend(strconv.FormatInt(send, 10)+"ugnot").URL() + ")")
	b.WriteString(" (sends 2% extra in case the price moves; the change is refunded) · ")
	b.WriteString("[Add item](" + txlink.NewLink("Add").AddArgs("id", strconv.Itoa(t.ID)).URL() + ")\n")
	return b.String()
}

func renderJSON() string {
	var items []string
	n := 0
	tabs.ReverseIterate("", "", func(_ string, v any) bool {
		t := v.(*Tab)
		var its []string
		for _, it := range t.Items {
			its = append(its, ufmt.Sprintf("{\"name\":\"%s\",\"cents\":%d}", it.Name, it.Cents))
		}
		items = append(items, ufmt.Sprintf("{\"id\":%d,\"title\":\"%s\",\"bartender\":\"%s\",\"total\":%d,\"paid\":%t,\"payer\":\"%s\",\"paidUgnot\":%d,\"paidPrice\":%d,\"items\":[%s]}",
			t.ID, t.Title, t.Bartender.String(), Total(t.ID), t.Paid, t.Payer.String(), t.PaidUgnot, t.PaidPrice, strings.Join(its, ",")))
		n++
		return n >= 100
	})
	return ufmt.Sprintf("{\"settledCents\":%d,\"tabs\":[%s]}", paidTotalCents, strings.Join(items, ","))
}
